window.NMNRT_LEARNING_DATA = {"version":1,"release":"2.3","bankId":"nmnrt-reviewed-2026-09-29-v2.1","sourceRelease":"2.2","basis":"Diễn đạt lại đáp án và giải thích đã biên tập của NMNRT 2.2; không thêm kiến thức vào các mục nguồn còn trống.","points":[{"id":"qa21-g9-l1-s0-614d23a8b6","title":"Sinh học nghiên cứu gì","takeaway":"Sinh học nghiên cứu sinh vật và các quá trình sống, không chỉ riêng người, động vật hay thực vật."},{"id":"qa21-g9-l1-s0-6f32f2cfd6","title":"Sinh quyển","takeaway":"Sinh quyển là cấp tổ chức bao gồm toàn bộ phần Trái Đất có sự sống."},{"id":"qa21-g9-l1-s0-2d17be6344","title":"Nghiên cứu ứng dụng","takeaway":"Dùng kiến thức sinh học để tạo giống cây mới là nghiên cứu ứng dụng."},{"id":"qa21-g9-l1-s1-400ff2355d","title":"Vận dụng kiến thức","takeaway":"Đề xuất cách bảo vệ nguồn nước là dùng kiến thức sinh học để xử lí một vấn đề thực tế."},{"id":"qa21-g9-l1-s1-d2144cc986","title":"Sinh học trong đời sống","takeaway":"Kiến thức sinh học gắn trực tiếp với sức khỏe và môi trường."},{"id":"qa21-g9-l1-s2-b71e986802","title":"Hoạt động sống","takeaway":"Tiêu hóa thức ăn là hoạt động sống: cơ thể biến đổi thức ăn để sử dụng.","detail":"Tiêu hóa biến đổi thức ăn để cơ thể sử dụng. Đây là một quá trình của cơ thể sống."},{"id":"qa21-g9-l2-s0-6e87567976","title":"Quan sát","takeaway":"Đếm số loài chim trong công viên là quan sát: ghi nhận mà không chủ động đổi điều kiện sống."},{"id":"qa21-g9-l2-s0-e42a77c4db","title":"Thực nghiệm","takeaway":"Trồng hai nhóm cây giống nhau và chỉ đổi ánh sáng là thực nghiệm khoa học."},{"id":"qa21-g9-l2-s0-1849b168ab","title":"Nghiên cứu tài liệu","takeaway":"Tổng hợp kết quả từ bài báo khoa học là nghiên cứu tài liệu, không phải tạo thí nghiệm mới."},{"id":"qa21-g9-l2-s0-d21898a48a","title":"Chọn phương pháp","takeaway":"Câu hỏi nghiên cứu quyết định loại bằng chứng và phương pháp cần sử dụng."},{"id":"qa21-g9-l2-s1-57239ad233","title":"Giả thuyết khoa học","takeaway":"Một giả thuyết khoa học phải có thể được kiểm tra bằng bằng chứng."},{"id":"qa21-g9-l2-s1-6996de64d6","title":"Nhóm đối chứng","takeaway":"Nhóm đối chứng giúp phân biệt tác động của yếu tố đang khảo sát với các ảnh hưởng khác."},{"id":"qa21-g10-l1-s1-cb7e6d8dce","title":"Đối tượng của Sinh học","takeaway":"Sinh học nghiên cứu sinh vật và các quá trình sống, từ cấp phân tử đến sinh quyển."},{"id":"qa21-g10-l1-s1-cca9c59548","title":"Phạm vi sinh quyển","takeaway":"Sinh quyển bao gồm các hệ sinh thái có sự sống trên Trái Đất."},{"id":"qa21-g10-l1-s1-becd08d90d","title":"Nghiên cứu cơ bản","takeaway":"Tìm hiểu cơ chế tế bào phân chia, chưa nhằm tạo sản phẩm, là nghiên cứu cơ bản."},{"id":"qa21-g10-l1-s2-3dcbc948fd","title":"Ứng dụng pháp y","takeaway":"Phân tích DNA để hỗ trợ nhận dạng trong điều tra là một ứng dụng của pháp y."},{"id":"qa21-g10-l1-s2-78741c0310","title":"Giống kháng virus","takeaway":"Tạo giống cây kháng virus nhằm giảm thiệt hại do bệnh virus gây ra."},{"id":"qa21-g10-l1-s3-21ac92e994","title":"Phát triển bền vững","takeaway":"Phát triển bền vững đáp ứng nhu cầu hiện tại mà không làm hại khả năng đáp ứng nhu cầu của thế hệ sau."},{"id":"qa21-g10-l1-s3-eabb0d2275","title":"Khai thác và phục hồi","takeaway":"Khai thác rừng đi đôi với phục hồi giúp duy trì tài nguyên lâu dài."},{"id":"qa21-g10-l1-s4-31b5767ff1","title":"Công nghệ phỏng sinh học","takeaway":"Phỏng sinh học mô phỏng đặc điểm hoặc cơ chế của sinh vật để thiết kế công nghệ."},{"id":"qa21-g10-l1-s4-4d9692d111","title":"Đạo đức và tác động xã hội","takeaway":"Ứng dụng sinh học cần cân nhắc cả hiệu quả, đạo đức và tác động tới con người, môi trường."},{"id":"qa21-g10-l1-s6-93835f88d3","title":"Bảo tồn loài","takeaway":"Bảo vệ sinh cảnh và phục hồi quần thể cùng góp phần bảo tồn loài đang bị đe dọa."},{"id":"qa21-g10-l2-s1-23d8d1d08a","title":"Phương pháp quan sát","takeaway":"Đo chiều cao cây mà không thay đổi điều kiện là quan sát."},{"id":"qa21-g10-l2-s1-87e0db03b3","title":"Dấu hiệu của thực nghiệm","takeaway":"Thực nghiệm chủ động thay đổi và kiểm soát điều kiện để kiểm tra giả thuyết."},{"id":"qa21-g10-l2-s2-bf8a157276","title":"Độ phóng đại kính hiển vi","takeaway":"Độ phóng đại tổng = thị kính × vật kính. Thị kính 10× và vật kính 40× cho 400×."},{"id":"qa21-g10-l2-s2-b7f7bc224f","title":"Lam kính và lamen","takeaway":"Lam kính và lamen dùng để chuẩn bị tiêu bản quan sát dưới kính hiển vi."},{"id":"qa21-g10-l2-s3-bc59f4565c","title":"Kiểm tra giả thuyết","takeaway":"Sau khi nêu giả thuyết, cần thiết kế quan sát hoặc thí nghiệm để kiểm tra nó."},{"id":"qa21-g10-l2-s4-ace0609bbc","title":"Tin sinh học","takeaway":"Tin sinh học kết hợp sinh học, khoa học máy tính và thống kê để xử lí dữ liệu sinh học."},{"id":"qa21-g10-l2-s4-57aeeb4d1e","title":"So sánh hệ gene","takeaway":"So sánh trình tự các hệ gene bằng công cụ tính toán là ứng dụng tin sinh học."},{"id":"qa21-g10-l2-s5-0d9a985b0a","title":"Trung thực với số liệu","takeaway":"Báo cáo trung thực giúp kết luận dựa trên bằng chứng thực, không phải kết quả mong muốn."},{"id":"qa21-g10-l2-s6-2202eb13e0","title":"Biến khảo sát","takeaway":"Khi thử ảnh hưởng của nước lên cây, thay đổi lượng nước tưới và giữ các điều kiện khác tương đương."},{"id":"qa21-g10-l2-s6-dd8fb1cced","title":"Giảm yếu tố gây nhiễu","takeaway":"Các nhóm thử nghiệm nước tưới cần cây cùng giống, tuổi và kích thước ban đầu gần nhau."},{"id":"qa21-g10-l3-s1-ae572ae8f4","title":"Đơn vị sống cơ bản","takeaway":"Tế bào là đơn vị nhỏ nhất có đầy đủ các đặc trưng cơ bản của sự sống."},{"id":"qa21-g10-l3-s2-f7a1202cf7","title":"Đặc tính nổi trội","takeaway":"Sự tương tác giữa các thành phần tạo nên tính chất mới ở cấp tổ chức cao hơn."},{"id":"qa21-g10-l3-s2-aba5a7b69a","title":"Tổ chức theo thứ bậc","takeaway":"Cấp tổ chức thấp cấu thành cấp cao; các cấp liên hệ qua vật chất, năng lượng và thông tin."},{"id":"qa21-g10-l3-s3-e338cd7700","title":"Mô","takeaway":"Các tế bào có cấu tạo và chức năng tương tự, phối hợp với nhau, thường tạo thành mô."},{"id":"qa21-g10-l3-s3-40b2be2372","title":"Từ tế bào đến cơ thể","takeaway":"Thứ tự từ nhỏ đến lớn: tế bào → mô → cơ quan → cơ thể."},{"id":"qa21-g10-l4-s1-51d2222b99","title":"Nguồn gốc tế bào mới","takeaway":"Theo học thuyết tế bào, tế bào mới hình thành từ tế bào có trước."},{"id":"qa21-g10-l4-s1-6a4e590f26","title":"Màng nhân","takeaway":"Ở tế bào nhân thực, màng nhân ngăn cách nhân với tế bào chất."},{"id":"qa21-g10-l4-s2-5b77613a2b","title":"Liên kết peptide","takeaway":"Liên kết peptide nối các amino acid thành chuỗi polypeptide."},{"id":"qa21-g10-l4-s2-1cbf259490","title":"Liên kết phosphodiester","takeaway":"Liên kết phosphodiester nối các nucleotide trên cùng một mạch DNA."},{"id":"qa21-g10-l5-s2-b0d66d1c31","title":"Bộ khung carbon","takeaway":"Carbon tạo bộ khung chủ yếu của phân tử hữu cơ nhờ khả năng tạo bốn liên kết cộng hóa trị."},{"id":"qa21-g10-l5-s2-97300aa0d6","title":"Phân tử sinh học","takeaway":"Phân tử sinh học tham gia cấu tạo hoặc hoạt động của hệ sống; chúng cũng có thể được tách chiết ngoài tế bào."},{"id":"qa21-g10-l5-s3-cede4aeb45","title":"Đường đơn","takeaway":"Galactose là đường đơn; sucrose là đường đôi; tinh bột và cellulose là đường đa."},{"id":"qa21-g10-l5-s3-9fce724a68","title":"Liên kết giữa các đơn vị đường","takeaway":"Liên kết glycosidic nối hai đường đơn trong đường đôi."},{"id":"qa21-g10-l5-s3-925089990b","title":"Cellulose","takeaway":"Cellulose là polysaccharide có vai trò cấu trúc chủ yếu trong thành tế bào thực vật."},{"id":"qa21-g10-l5-s3-c493de9f91","title":"Tinh bột","takeaway":"Tinh bột được cấu tạo từ nhiều đơn vị glucose."},{"id":"qa21-g10-l5-s3-3ba67a1f49","title":"Đường 5C và 6C","takeaway":"Đường đơn không chỉ có 6 carbon: ribose có 5 carbon, glucose có 6 carbon."},{"id":"qa21-g10-l5-s4-03985e1467","title":"Lớp kép phospholipid","takeaway":"Phospholipid tạo lớp kép nền tảng của màng sinh chất nhờ đầu ưa nước và đuôi kị nước."},{"id":"qa21-g10-l5-s4-fdc2ce3ea8","title":"Tính kị nước của lipid","takeaway":"Nhiều lipid ít tan trong nước vì chứa các vùng hydrocarbon không phân cực."},{"id":"qa21-g10-l5-s4-d5fa725d78","title":"Mỡ và dầu","takeaway":"Mỡ và dầu chủ yếu dự trữ năng lượng cho tế bào và cơ thể."},{"id":"qa21-g10-l5-s4-e888285d2e","title":"Cholesterol","takeaway":"Cholesterol vừa góp phần cấu tạo màng, vừa là tiền chất của nhiều hormone steroid ở động vật."},{"id":"qa21-g10-l5-s5-bbcb31dc3e","title":"Đơn phân protein","takeaway":"Amino acid là đơn phân của protein; chúng nối với nhau bằng liên kết peptide."},{"id":"qa21-g10-l5-s5-00381c7b39","title":"Nhóm R","takeaway":"Nhóm R tạo nên sự khác nhau về tính chất giữa các amino acid thông thường."},{"id":"qa21-g10-l5-s5-d87a84102d","title":"Kháng thể","takeaway":"Kháng thể là protein nhận biết và gắn đặc hiệu với kháng nguyên."},{"id":"qa21-g10-l5-s5-d63096be1e","title":"Thụ thể","takeaway":"Protein tiếp nhận tín hiệu phù hợp và khởi đầu đáp ứng của tế bào đóng vai trò thụ thể."},{"id":"qa21-g10-l5-s6-0d7b6c03b0","title":"Thông tin trong DNA","takeaway":"Thông tin di truyền được ghi chủ yếu trong trình tự nucleotide của DNA."},{"id":"qa21-g10-l5-s6-2f285e29ac","title":"Hai mạch DNA","takeaway":"Liên kết hydrogen giữa các base bổ sung góp phần giữ hai mạch DNA với nhau."},{"id":"qa21-g10-l5-s6-d55d8c8a43","title":"Vai trò tRNA","takeaway":"tRNA vận chuyển amino acid đến ribosome và nhận diện codon bằng anticodon."},{"id":"qa21-g10-l5-s6-52a38b07bf","title":"Vai trò mRNA","takeaway":"mRNA làm khuôn để ribosome tổng hợp chuỗi polypeptide."},{"id":"qa21-g10-l5-s6-69853c3ace","title":"Vai trò rRNA","takeaway":"rRNA cùng protein tạo ribosome và tham gia xúc tác tạo liên kết peptide."},{"id":"qa21-g10-l7-s1-3f19b04047","title":"Nhân sơ","takeaway":"Tế bào nhân sơ có DNA và ribosome nhưng không có nhân được bao bọc bởi màng."},{"id":"qa21-g10-l7-s1-29114a414b","title":"Phân đôi ở vi khuẩn","takeaway":"Vi khuẩn thường sinh sản bằng phân đôi, không phải nguyên phân kiểu nhân thực."},{"id":"qa21-g10-l7-s2-59d9948e6a","title":"Vùng nhân","takeaway":"DNA chính của vi khuẩn điển hình nằm trong vùng nhân, không có màng nhân bao bọc."},{"id":"qa21-g10-l7-s2-7597b5e867","title":"Plasmid","takeaway":"Một số plasmid mang gene kháng kháng sinh; không phải mọi plasmid đều có chức năng này."},{"id":"qa21-g10-l7-s2-9e5dd2e5a6","title":"Ribosome vi khuẩn","takeaway":"Ribosome vi khuẩn tổng hợp protein bằng cách dịch mã mRNA."},{"id":"qa21-g10-l7-s2-58e5b58163","title":"Roi và vận động","takeaway":"Roi giúp nhiều vi khuẩn di chuyển; nhiều pili lại giúp bám hoặc tiếp hợp."},{"id":"qa21-g10-l7-s5-6667c6fa16","title":"Liên cầu và tụ cầu","takeaway":"Cầu khuẩn xếp thành chuỗi là liên cầu khuẩn; xếp thành cụm giống chùm nho là tụ cầu."},{"id":"qa21-g10-l7-s5-63fe2132a4","title":"Trực khuẩn","takeaway":"Trực khuẩn là tên gọi vi khuẩn hình que, không tự nói lên loài hay khả năng gây bệnh."},{"id":"qa21-g10-l7-s6-b8a0d7f5aa","title":"Peptidoglycan","takeaway":"Peptidoglycan là thành phần chính của thành tế bào vi khuẩn, hỗ trợ hình dạng và chống áp suất thẩm thấu."},{"id":"qa21-g10-l7-s6-0a55fb309d","title":"Màng sinh chất vi khuẩn","takeaway":"Màng sinh chất trực tiếp kiểm soát các chất ra vào tế bào vi khuẩn."},{"id":"qa21-g10-l7-s6-bf5388234d","title":"Thành tế bào và sức trương","takeaway":"Trong môi trường nhược trương, nước có thể vào vi khuẩn; thành tế bào chịu lực giúp hạn chế vỡ."},{"id":"qa21-g10-l7-s6-de8094bdde","title":"Ribosome 70S","takeaway":"Ribosome 70S gồm tiểu đơn vị 50S và 30S. S là hệ số lắng, không cộng số học."},{"id":"qa21-g10-l7-s7-2ae1b739e7","title":"Gram âm","takeaway":"Vi khuẩn Gram âm có lớp peptidoglycan mỏng và màng ngoài chứa lipopolysaccharide (LPS)."},{"id":"qa21-g10-l7-s7-7f57cf4881","title":"Gram dương","takeaway":"Thành tế bào vi khuẩn Gram dương thường có lớp peptidoglycan dày."},{"id":"qa21-g10-l7-s8-c5bc19c705","title":"Vai trò nội bào tử","takeaway":"Nội bào tử giúp vi khuẩn tồn tại khi điều kiện bất lợi; tạo nội bào tử không phải tăng số lượng tế bào."},{"id":"qa21-g10-l7-s8-729c9fea96","title":"Trạng thái nội bào tử","takeaway":"Nội bào tử có chuyển hóa rất thấp và khả năng đề kháng cao so với tế bào đang sinh trưởng."},{"id":"qa21-g10-l7-s9-1a6f32a8ac","title":"Mycoplasma","takeaway":"Mycoplasma không có thành tế bào nên không có đích peptidoglycan của thuốc ức chế tổng hợp thành."},{"id":"qa21-g10-l7-s9-e5ae942cf0","title":"Vi khuẩn lam","takeaway":"Vi khuẩn lam điển hình quang tự dưỡng: dùng ánh sáng, cố định CO₂ và giải phóng oxygen."},{"id":"qa21-g10-l7-s9-5495cebd11","title":"Streptomyces","takeaway":"Nhiều xạ khuẩn Streptomyces tạo chất chuyển hóa có hoạt tính kháng sinh."},{"id":"qa21-g10-l7-s10-32d48f9d6b","title":"Nucleoid","takeaway":"Nucleoid nghĩa là vùng nhân của tế bào nhân sơ, không phải nhân có màng."},{"id":"qa21-g10-l7-s10-8c3669b10a","title":"Flagellum","takeaway":"Flagellum nghĩa là roi, thường tham gia vận động tế bào."},{"id":"qa21-g10-l8-s1-ad867c2bd5","title":"Nhóm sinh vật nhân thực","takeaway":"Nấm, động vật và thực vật là sinh vật nhân thực; vi khuẩn và cổ khuẩn là nhân sơ."},{"id":"qa21-g10-l8-s1-964651f423","title":"Bào quan có màng","takeaway":"Tế bào nhân thực có các bào quan có màng bao bọc, tạo những khoang chuyên hóa chức năng."},{"id":"qa21-g10-l8-s2-a28672245d","title":"Chức năng của nhân","takeaway":"Nhân chứa phần lớn DNA và điều hòa hoạt động tế bào; DNA cũng có trong ti thể và lục lạp."},{"id":"qa21-g10-l12-s1-c1e12c37ba","title":"Phối tử và thụ thể","takeaway":"Phối tử gắn đặc hiệu với thụ thể phù hợp để khởi đầu truyền tin."},{"id":"qa21-g10-l12-s1-3a1c6685c7","title":"Vai trò truyền tin","takeaway":"Truyền tin giúp phối hợp và điều chỉnh hoạt động tế bào theo điều kiện bên trong, bên ngoài."},{"id":"qa21-g10-l12-s1-4e022032c2","title":"Tế bào đích","takeaway":"Một hormone chỉ gây đáp ứng ở tế bào có thụ thể và đường đáp ứng phù hợp."},{"id":"qa21-g10-l12-s2-7d2318ba74","title":"Tự tiết","takeaway":"Trong truyền tin tự tiết, tế bào nhận tín hiệu do chính nó tiết ra."},{"id":"qa21-g10-l12-s2-0f6ea6009a","title":"Nội tiết","takeaway":"Truyền tin nội tiết đưa hormone theo máu đến tế bào đích ở xa."},{"id":"qa21-g10-l12-s2-e3d385c985","title":"Cận tiết","takeaway":"Truyền tin cận tiết chủ yếu tác động lên các tế bào lân cận."},{"id":"qa21-g10-l12-s3-231d53c098","title":"Ba bước truyền tin","takeaway":"Truyền tin trong tế bào gồm: tiếp nhận → truyền tin → đáp ứng."},{"id":"qa21-g10-l12-s3-875a833496","title":"Cùng tín hiệu, khác đáp ứng","takeaway":"Cùng một tín hiệu có thể gây đáp ứng khác nhau vì các loại tế bào có hệ thụ thể và protein đáp ứng khác nhau."},{"id":"qa21-g10-l12-s4-6ed987049f","title":"Phối tử ưa nước","takeaway":"Phối tử ưa nước khó qua lớp kép lipid thường gắn vào thụ thể trên bề mặt tế bào."},{"id":"qa21-g10-l12-s4-aa130357ab","title":"Thụ thể của steroid","takeaway":"Hormone steroid thường đi qua màng và gắn với thụ thể nội bào."},{"id":"qa21-g10-l12-s5-af7b7315fd","title":"Công tắc G-protein","takeaway":"Tiểu đơn vị α của G-protein thường hoạt động khi gắn GTP; thủy phân GTP góp phần tắt tín hiệu."},{"id":"qa21-g10-l12-s5-00c699ff24","title":"Chất truyền tin cAMP","takeaway":"Adenylyl cyclase chuyển ATP thành cAMP, một chất truyền tin thứ hai."},{"id":"qa21-g10-l12-s7-83bf130114","title":"Epinephrine ở gan","takeaway":"Epinephrine thúc đẩy phân giải glycogen ở gan để huy động nguồn glucose."},{"id":"qa21-g10-l13-s1-3ca8bb1973","title":"Chuyển hóa năng lượng","takeaway":"Tế bào chuyển năng lượng từ dạng này sang dạng khác, không tạo mới hay hủy năng lượng."},{"id":"qa21-g10-l13-s2-d43d4541cc","title":"Tác dụng enzyme","takeaway":"Enzyme tăng tốc phản ứng bằng cách hạ năng lượng hoạt hóa, không làm đổi cân bằng nhiệt động học."},{"id":"qa21-g10-l13-s2-f051452d39","title":"Cơ chất","takeaway":"Cơ chất là phân tử được enzyme tác động: nó gắn vào trung tâm hoạt động rồi được chuyển thành sản phẩm."},{"id":"qa21-g10-l14-s2-5764320cd6","title":"Đồng hóa","takeaway":"Tổng hợp protein từ amino acid là đồng hóa: xây dựng phân tử phức tạp và thường cần năng lượng."},{"id":"qa21-g10-l14-s2-2011b83644","title":"Liên hệ dị hóa – đồng hóa","takeaway":"Phân giải cung cấp vật liệu và năng lượng cho tổng hợp; hai quá trình liên kết qua chất trung gian."},{"id":"qa21-g10-l16-s1-ae35096c28","title":"Kết quả nguyên phân","takeaway":"Nguyên phân bình thường tạo hai tế bào con có số lượng nhiễm sắc thể giống nhau và giống tế bào mẹ."},{"id":"qa21-g10-l20-s0-6e514fc7e4","title":"Kích thước nhỏ, trao đổi nhanh","takeaway":"Tỉ lệ diện tích bề mặt/thể tích lớn giúp nhiều vi sinh vật trao đổi chất với môi trường hiệu quả."},{"id":"qa21-g10-l20-s0-6b7f90e557","title":"Vi sinh vật là cách gọi chung","takeaway":"Vi sinh vật gồm nhiều nhóm có kích thước hiển vi, cả nhân sơ và nhân thực; không phải một nhóm phân loại duy nhất."},{"id":"qa21-g10-l20-s0-0acc9dbf16","title":"Biến đổi di truyền","takeaway":"Đột biến gene tạo biến đổi di truyền mới; thay đổi sinh lí tạm thời không đồng nghĩa đột biến."},{"id":"qa21-g10-l20-s2-546ddd9a00","title":"Quang tự dưỡng","takeaway":"Quang tự dưỡng dùng ánh sáng làm nguồn năng lượng và chất vô cơ như CO₂ làm nguồn carbon."},{"id":"qa21-g10-l20-s2-99ba843e81","title":"Hóa dị dưỡng","takeaway":"Hóa dị dưỡng dùng chất hữu cơ làm nguồn carbon và năng lượng hóa học."},{"id":"qa21-g10-l20-s2-a6d4825952","title":"Quang dị dưỡng","takeaway":"Quang dị dưỡng dùng ánh sáng nhưng lấy carbon từ chất hữu cơ."},{"id":"qa21-g10-l20-s3-865be6ac9d","title":"Phân lập vi sinh vật","takeaway":"Phân lập nhằm tách đối tượng khỏi hỗn hợp để thu được quần thể nuôi cấy thuần."},{"id":"qa21-g10-l20-s3-760c27222e","title":"Môi trường tổng hợp","takeaway":"Môi trường tổng hợp có thành phần và hàm lượng hóa học xác định."},{"id":"qa21-g10-l20-s3-88ccf31886","title":"Môi trường bán tổng hợp","takeaway":"Môi trường bán tổng hợp phối hợp dịch chiết tự nhiên với các hóa chất xác định."},{"id":"qa21-g10-l20-s4-215950f375","title":"Lipid màng cổ khuẩn","takeaway":"Lipid màng cổ khuẩn điển hình có chuỗi hydrocarbon nối với glycerol bằng liên kết ether."},{"id":"qa21-g10-l20-s4-fdff2d1e8a","title":"Sinh methane","takeaway":"Các sinh vật sinh methane điển hình thuộc miền Archaea và hoạt động trong điều kiện kị khí."},{"id":"qa21-g10-l20-s4-43296a7410","title":"Bacteriorhodopsin","takeaway":"Bacteriorhodopsin giúp một số cổ khuẩn ưa mặn dùng ánh sáng để bơm proton."},{"id":"qa21-g10-l20-s5-09fbaa5d41","title":"Quang hợp ở vi tảo","takeaway":"Vi tảo nhân thực thực hiện quang hợp nhờ lục lạp."},{"id":"qa21-g10-l20-s5-6ad72f4827","title":"Tảo chết và thiếu oxygen","takeaway":"Khi tảo chết hàng loạt, vi sinh vật phân hủy tiêu thụ nhiều oxygen hòa tan, có thể làm cá thiếu oxygen."},{"id":"qa21-g10-l20-s5-643667f8c2","title":"Vỏ tảo silic","takeaway":"Vỏ tảo silic chứa silica; không phải thành của mọi vi tảo đều là cellulose."},{"id":"qa21-g10-l20-s6-bd1cb9e09b","title":"Nấm men là nhân thực","takeaway":"Nấm men thuộc giới nấm, có nhân được màng bao bọc và các bào quan nhân thực."},{"id":"qa21-g10-l20-s6-67cd614b67","title":"Nảy chồi ở nấm men","takeaway":"Nấm men bánh mì thường sinh sản vô tính bằng nảy chồi."},{"id":"qa21-g10-l20-s6-a443c31cc4","title":"Vì sao bột bánh nở","takeaway":"Nấm men lên men đường tạo CO₂; khí giữ trong khối bột làm bột nở."},{"id":"qa21-g10-l20-s6-fbcf872a7c","title":"Dinh dưỡng của nấm men","takeaway":"Nấm men chủ yếu hóa dị dưỡng, dùng chất hữu cơ làm nguồn carbon và năng lượng."},{"id":"qa21-g10-l20-s7-8445f6baca","title":"Nấm sợi","takeaway":"Các sợi nấm phân nhánh tạo thành hệ sợi, cấu tạo chủ yếu của cơ thể nấm sợi."},{"id":"qa21-g10-l20-s7-afcace54b1","title":"Phân mảnh ở nấm","takeaway":"Một đoạn sợi nấm phát triển thành cơ thể mới là sinh sản vô tính bằng phân mảnh."},{"id":"qa21-g10-l20-s7-d31a641742","title":"Bào tử đính","takeaway":"Bào tử đính hình thành bên ngoài túi bào tử, trên cấu trúc mang bào tử."},{"id":"qa21-g10-l20-s8-a0a782363c","title":"Chân giả của amip","takeaway":"Amip thường di chuyển nhờ chân giả, được tạo bởi dòng tế bào chất và sự đổi hình dạng."},{"id":"qa21-g10-l20-s8-3d60f0e81b","title":"Vai trò của kén","takeaway":"Kén giúp một số nguyên sinh vật tồn tại trong điều kiện môi trường bất lợi."},{"id":"qa21-g10-l21-s1-f321b8cde6","title":"DNA trong phân đôi","takeaway":"Vi khuẩn phải sao chép và phân phối DNA trước khi hoàn tất phân chia tế bào."},{"id":"qa21-g10-l21-s1-985aad7388","title":"Ví dụ ba lần phân đôi","takeaway":"Từ 1 vi khuẩn, sau 3 lần phân đôi và không có tế bào chết: 1 × 2³ = 8 tế bào."},{"id":"qa21-g10-l21-s4-347af7ceaf","title":"Nảy chồi khác phân đôi","takeaway":"Trong nảy chồi, tế bào mới lớn lên từ một vùng của tế bào mẹ, không chia thành hai phần gần tương đương."},{"id":"qa21-g10-l28-s0-d9792d6729","title":"Hai thành phần tinh bột","takeaway":"Amylopectin có cấu trúc phân nhánh; amylose chủ yếu không phân nhánh."},{"id":"qa21-g10-l28-s0-558ffe9fc0","title":"Cấu tạo triglyceride","takeaway":"Một triglyceride gồm glycerol liên kết với 3 acid béo."},{"id":"qa21-g10-l28-s0-b5dc48973f","title":"Steroid","takeaway":"Cholesterol thuộc nhóm steroid, có bộ khung bốn vòng carbon hợp nhất."},{"id":"qa21-g10-l28-s1-dff3fce875","title":"Nhận biết tinh bột","takeaway":"Iodine tạo màu xanh tím hoặc xanh đen rõ với tinh bột."},{"id":"qa21-g10-l28-s1-828e9a7efe","title":"Nhiệt độ và phức iodine","takeaway":"Màu phức tinh bột–iodine có thể mất khi nóng và trở lại khi nguội do cấu dạng và độ bền phức thay đổi."},{"id":"qa21-g10-l29-s0-3831a40a06","title":"Glycoprotein","takeaway":"Glycoprotein gồm protein liên kết với chuỗi carbohydrate; phần đường có thể tham gia nhận diện tế bào."},{"id":"qa21-g10-l29-s0-1349533360","title":"Đường bài tiết protein","takeaway":"Protein đi vào đường bài tiết thường được tổng hợp ở ribosome gắn lưới nội chất hạt."},{"id":"qa21-g10-l29-s0-7e043a2a73","title":"Gắn đường lên protein","takeaway":"Gắn và chỉnh sửa đường trên nhiều protein bài tiết diễn ra ở lưới nội chất và Golgi."},{"id":"qa21-g10-l29-s0-7ccb7d9b23","title":"Môi trường acid của lysosome","takeaway":"Bơm proton đưa H⁺ vào lòng lysosome, tạo môi trường acid phù hợp cho enzyme thủy phân."},{"id":"qa21-g10-l29-s0-9225fae09c","title":"Gradient proton ở ti thể","takeaway":"Chuỗi truyền electron bơm H⁺ từ chất nền ra khoang gian màng; H⁺ trở về qua ATP synthase."},{"id":"qa21-g10-l30-s0-e0c38d9383","title":"Ức chế cạnh tranh","takeaway":"Chất ức chế cạnh tranh thuận nghịch thường cạnh tranh với cơ chất tại trung tâm hoạt động của enzyme."},{"id":"qa21-g10-l30-s0-2312847b45","title":"Vmax trong ức chế cạnh tranh","takeaway":"Trong mô hình cạnh tranh thuận nghịch đơn giản, Vmax không đổi nhưng Km biểu kiến tăng."},{"id":"qa21-g10-l30-s0-0108372b5c","title":"Tăng cơ chất","takeaway":"Tăng nồng độ cơ chất thường làm giảm tác động của chất ức chế cạnh tranh thuận nghịch."},{"id":"qa21-g10-l30-s1-cf65123e89","title":"Sản phẩm đường phân","takeaway":"Đường phân chuyển một glucose thành hai pyruvate, đồng thời thu ròng ATP và NADH."},{"id":"qa21-g10-l30-s1-479f8e95c6","title":"Chất mang electron","takeaway":"NADH và FADH₂ chuyển electron thu được khi oxi hóa chất hữu cơ tới chuỗi hô hấp."},{"id":"qa21-g10-l30-s1-2ffe13a3ce","title":"Vai trò lên men lactate","takeaway":"Lên men lactate tái tạo NAD⁺, giúp đường phân tiếp tục."},{"id":"qa21-g10-l30-s1-522d6807c0","title":"Không nhầm lactate với đau cơ muộn","takeaway":"Không thể giải thích đau cơ xuất hiện muộn sau vận động bằng lactate tích tụ."},{"id":"qa21-g10-l31-s0-3b46c9706b","title":"Tín hiệu hoạt hóa trứng","takeaway":"Dao động Ca²⁺ trong bào tương là tín hiệu quan trọng khi hoạt hóa trứng ở động vật có vú."},{"id":"qa21-g10-l31-s0-c26bc42760","title":"Vai trò IP₃","takeaway":"IP₃, một sản phẩm của phospholipase C, kích thích giải phóng Ca²⁺ từ lưới nội chất."},{"id":"qa21-g10-l32-s0-1a0c6f842d","title":"Nhân đôi DNA ti thể","takeaway":"DNA ti thể không nhất thiết chỉ nhân đôi trong pha S của nhân; nó được điều hòa khác DNA nhân."},{"id":"qa21-g11-l1-s1-e3257161b7","title":"Vật liệu và năng lượng","takeaway":"Trao đổi chất cung cấp vật liệu xây dựng cơ thể và nguồn năng lượng cho hoạt động sống."},{"id":"qa21-g11-l1-s1-cd75b9ca73","title":"Chất thải và nội môi","takeaway":"Loại bỏ chất thải chuyển hóa góp phần duy trì cân bằng nội môi."},{"id":"qa21-g11-l1-s1-b5cb797896","title":"Nguồn carbon quang hợp","takeaway":"Carbon để cây tổng hợp carbohydrate bằng quang hợp chủ yếu đến từ CO₂."},{"id":"qa21-g11-l1-s2-1fe62b1029","title":"Vận chuyển sản phẩm hữu cơ","takeaway":"Ở thực vật có mạch, sản phẩm hữu cơ được vận chuyển chủ yếu qua mạch rây."},{"id":"qa21-g11-l1-s2-046628a4ec","title":"Tổng hợp vật chất","takeaway":"Đồng hóa xây dựng chất phức tạp từ chất đơn giản và thường cần năng lượng."},{"id":"qa21-g11-l1-s2-24f43d01b6","title":"Điều hòa ở động vật","takeaway":"Hệ thần kinh và hệ nội tiết phối hợp điều hòa hoạt động trao đổi chất ở động vật."},{"id":"qa21-g11-l1-s3-5e37e1bade","title":"Chuyển năng lượng khi quang hợp","takeaway":"Quang hợp chuyển quang năng thành hóa năng tích lũy trong sản phẩm."},{"id":"qa21-g11-l1-s3-3300fe4134","title":"ATP","takeaway":"ATP thường trực tiếp cung cấp năng lượng cho công tế bào thông qua phản ứng thủy phân được ghép cặp."},{"id":"qa21-g11-l1-s3-d133472ddd","title":"Năng lượng phân tán","takeaway":"Trong chuyển hóa, một phần năng lượng phân tán ra dưới dạng nhiệt."},{"id":"qa21-g11-l1-s4-26830a408d","title":"Tế bào là cơ sở","takeaway":"Chuyển hóa cơ thể dựa trên chuyển hóa tế bào, nơi thực hiện các phản ứng sống."},{"id":"qa21-g11-l1-s5-46fe9b53f1","title":"Nguồn carbon tự dưỡng","takeaway":"Sinh vật tự dưỡng tổng hợp chất hữu cơ từ nguồn carbon vô cơ như CO₂."},{"id":"qa21-g11-l1-s5-32eda280f3","title":"Hai kiểu tự dưỡng","takeaway":"Quang tự dưỡng dùng năng lượng ánh sáng; hóa tự dưỡng thu năng lượng từ phản ứng hóa học."},{"id":"qa21-g11-l1-s5-fa5eacf5c3","title":"Dị dưỡng ở động vật","takeaway":"Động vật lấy carbon hữu cơ có sẵn từ thức ăn nên thuộc sinh vật dị dưỡng."},{"id":"qa21-g11-l2-s1-d564a24977","title":"Nước và sức trương","takeaway":"Nước tạo sức trương tế bào, giúp các mô non của cây giữ hình dạng và tư thế."},{"id":"qa21-g11-l2-s1-eada8daa0a","title":"Nước vận chuyển khoáng","takeaway":"Nước hòa tan nhiều ion khoáng, giúp chúng được hấp thụ và vận chuyển."},{"id":"qa21-g11-l2-s2-980c010916","title":"Lông hút","takeaway":"Lông hút là phần kéo dài của tế bào biểu bì rễ, làm tăng diện tích tiếp xúc và hấp thụ."},{"id":"qa21-g11-l2-s2-aaa7c6f098","title":"Thẩm thấu ở rễ","takeaway":"Nước qua màng vào tế bào lông hút chủ yếu bằng thẩm thấu, từ thế nước cao đến thế nước thấp."},{"id":"qa21-g11-l2-s2-5029e34076","title":"Hấp thụ khoáng chủ động","takeaway":"Vận chuyển ion ngược gradient điện hóa cần protein vận chuyển và nguồn năng lượng."},{"id":"qa21-g11-l2-s2-5b5847104d","title":"Đất mặn và hút nước","takeaway":"Đất quá mặn có thế nước thấp, khiến rễ khó hút nước và có thể mất nước."},{"id":"qa21-g11-l2-s3-4775b92ecb","title":"Mạch gỗ","takeaway":"Mạch gỗ dẫn nước và phần lớn ion khoáng từ rễ lên lá, chủ yếu nhờ lực hút do thoát hơi nước."},{"id":"qa21-g11-l2-s3-8a9646c4b5","title":"Hướng dòng mạch rây","takeaway":"Mạch rây vận chuyển từ cơ quan nguồn đến nơi sử dụng hoặc dự trữ; không cố định một hướng cho cả cây."},{"id":"qa21-g11-l2-s4-7dbce942fe","title":"Điều tiết thoát hơi nước","takeaway":"Khí khổng điều chỉnh phần lớn sự thoát hơi nước ở nhiều lá cây bằng thay đổi độ mở."},{"id":"qa21-g11-l2-s4-56060f3b02","title":"Tế bào bảo vệ trương nước","takeaway":"Khi tế bào bảo vệ trương nước, khe khí khổng thường mở rộng hơn."},{"id":"qa21-g11-l2-s4-2d7ead56ee","title":"ABA khi thiếu nước","takeaway":"Abscisic acid (ABA) thường thúc đẩy đóng khí khổng khi cây thiếu nước."},{"id":"qa21-g11-l2-s4-6321a19ec7","title":"Lực hút do thoát hơi nước","takeaway":"Nước bay hơi ở lá làm giảm thế nước và tạo lực hút kéo cột nước trong mạch gỗ."},{"id":"qa21-g11-l2-s4-88565097dc","title":"Cutin và chịu hạn","takeaway":"Lớp cutin dày giúp giảm mất nước qua bề mặt biểu bì lá."},{"id":"qa21-g11-l2-s5-77b112ce2f","title":"Vai trò nitrogen","takeaway":"Nitrogen là thành phần quan trọng của protein và nucleic acid."},{"id":"qa21-g11-l2-s5-772664da35","title":"Thiếu nitrogen","takeaway":"Cây thiếu nitrogen thường vàng lá và sinh trưởng chậm; biểu hiện còn tùy loài, điều kiện."},{"id":"qa21-g11-l2-s5-28b57b9845","title":"Bón thừa đạm","takeaway":"Bón thừa đạm có thể gây mất cân đối dinh dưỡng hoặc hại cây, không bảo đảm năng suất tăng."},{"id":"qa21-g11-l2-s6-f216acc436","title":"Hai dạng đạm khoáng","takeaway":"Cây thường hấp thụ nitrogen vô cơ từ đất dưới dạng NH₄⁺ và NO₃⁻."},{"id":"qa21-g11-l2-s6-9e28ece6e4","title":"Cố định nitrogen","takeaway":"Vi khuẩn nốt sần ở cây họ Đậu chuyển N₂ thành dạng nitrogen khử mà hệ cộng sinh sử dụng được."},{"id":"qa21-g11-l2-s7-8e5af7b931","title":"Ammonium hóa","takeaway":"Ammonium hóa chuyển nitrogen hữu cơ thành NH₄⁺."},{"id":"qa21-g11-l2-s7-f39e3e77f5","title":"Nitrate hóa","takeaway":"Nitrate hóa chuyển NH₄⁺ qua NO₂⁻ thành NO₃⁻ nhờ vi sinh vật."},{"id":"qa21-g11-l2-s7-be54098c79","title":"Phản nitrate hóa","takeaway":"Trong điều kiện thiếu oxygen, phản nitrate hóa chuyển nitrate thành khí nitrogen, làm giảm nguồn nitrate trong đất."},{"id":"qa21-g11-l2-s8-fd52adf0c0","title":"Đồng hóa nitrate","takeaway":"Trước khi đưa nitrogen của nitrate vào nhiều chất hữu cơ, cây khử nitrate qua nitrite thành ammonium."},{"id":"qa21-g11-l2-s8-afef5c3dc1","title":"Nitrate reductase","takeaway":"Nitrate reductase xúc tác bước khử NO₃⁻ thành NO₂⁻."},{"id":"qa21-g11-l2-s9-7b0413644c","title":"Ánh sáng hỗ trợ hấp thụ khoáng","takeaway":"Quang hợp tạo chất hữu cơ; hô hấp chất hữu cơ cung cấp năng lượng cho hấp thụ khoáng chủ động."},{"id":"qa21-g11-l2-s10-51c7fbdb10","title":"Nhiệt độ quá cao","takeaway":"Nhiệt độ vượt mức thích hợp có thể làm tổn thương tế bào, enzyme và giảm chức năng rễ."},{"id":"qa21-g11-l2-s11-6facc7d28a","title":"Ngập nước và rễ","takeaway":"Đất ngập lâu làm rễ thiếu oxygen cho hô hấp, giảm tạo ATP và hút khoáng chủ động."},{"id":"qa21-g11-l2-s11-46af61d3c4","title":"Độ ẩm và thoát hơi nước","takeaway":"Khi độ mở khí khổng không đổi, không khí ẩm hơn thường làm thoát hơi nước giảm."},{"id":"qa21-g11-l2-s12-6ecfb11de0","title":"Bón phân hợp lí","takeaway":"Loại phân, lượng, thời điểm và cách bón cần phù hợp loại cây, giai đoạn và nhu cầu dinh dưỡng."},{"id":"qa21-g11-l2-s12-f6200058af","title":"Phân tan quá nhiều","takeaway":"Bón quá nhiều phân tan làm thế nước đất thấp, có thể cản nước vào rễ hoặc kéo nước ra khỏi tế bào."},{"id":"qa21-g11-l3-s1-c29bbed813","title":"Lớp dầu trong thí nghiệm","takeaway":"Lớp dầu phủ mặt nước hạn chế bay hơi trực tiếp khỏi ống, giúp theo dõi hấp thụ nước của cây rõ hơn."},{"id":"qa21-g11-l3-s1-a72587ff71","title":"Ống đối chứng không có cây","takeaway":"Ống chỉ có nước giúp phân biệt biến đổi mực nước do cây với các nguyên nhân khác."},{"id":"qa21-g11-l3-s2-3ce102e01d","title":"Dòng nước màu","takeaway":"Ở cành hoa cắm vào nước màu, mạch gỗ thường được nhuộm trước vì chất màu đi theo dòng nước."},{"id":"qa21-g11-l3-s2-c82cdc39bf","title":"Đối chứng nước không màu","takeaway":"Cành cắm trong nước không màu giúp kiểm tra màu xuất hiện có liên quan đến dung dịch màu hay không."},{"id":"qa21-g11-l3-s3-e35e0db27c","title":"Chỉ thị độ ẩm","takeaway":"Giấy cobalt chloride khô chuyển từ xanh sang hồng khi gặp hơi ẩm, không phải do CO₂."},{"id":"qa21-g11-l3-s3-dc7753baa0","title":"So sánh hai mặt lá","takeaway":"Giấy cobalt chloride đổi màu nhanh hơn gợi ý mặt lá đó cung cấp hơi ẩm nhanh hơn khi các điều kiện khác tương đương."},{"id":"qa21-g11-l3-s4-676f4c2811","title":"Khí khổng","takeaway":"Khí khổng là cấu trúc ở biểu bì lá có thể đóng–mở để điều tiết trao đổi khí và thoát hơi nước."},{"id":"qa21-g11-l3-s4-53934c3ebb","title":"Hai tế bào bảo vệ","takeaway":"Hai tế bào bảo vệ điều chỉnh độ mở khí khổng bằng thay đổi sức trương."},{"id":"qa21-g11-l3-s5-37e88b2f75","title":"Thiết kế thí nghiệm tưới","takeaway":"Dùng cây cùng loài, gần cùng tuổi để hạn chế khác biệt không do lượng nước tưới."},{"id":"qa21-g11-l3-s5-89739107bf","title":"Úng vẫn có thể héo","takeaway":"Cây bị úng vẫn có thể héo vì rễ thiếu oxygen và suy giảm chức năng hấp thụ."},{"id":"qa21-g11-l3-s6-e26909026b","title":"Thủy canh","takeaway":"Thủy canh cung cấp khoáng qua dung dịch dinh dưỡng; cây không bắt buộc cần đất nếu có điều kiện thích hợp."},{"id":"qa21-g11-l3-s6-34b36f39ae","title":"Khí canh","takeaway":"Khí canh phun sương dinh dưỡng lên rễ trong không khí để cung cấp nước và khoáng."},{"id":"qa21-g11-l4-s1-e104f9ca9f","title":"Nơi quang hợp","takeaway":"Ở thực vật, quang hợp chủ yếu diễn ra trong lục lạp."},{"id":"qa21-g11-l4-s1-4a04da1623","title":"Nguyên liệu quang hợp","takeaway":"Quang hợp giải phóng oxygen dùng CO₂ cung cấp carbon, H₂O cung cấp electron và ánh sáng cung cấp năng lượng."},{"id":"qa21-g11-l4-s2-c0aa8a7c14","title":"Oxygen từ quang hợp","takeaway":"Quang hợp giải phóng O₂, góp phần duy trì hô hấp hiếu khí của sinh giới."},{"id":"qa21-g11-l4-s2-dafd8652a0","title":"Nền tảng chuỗi thức ăn","takeaway":"Quang hợp tạo chất hữu cơ từ carbon vô cơ, cung cấp nguồn carbon và năng lượng cho nhiều sinh vật."},{"id":"qa21-g11-l4-s3-38f906e083","title":"Diệp lục a","takeaway":"Diệp lục a ở trung tâm phản ứng thực hiện sự chuyển electron khởi đầu phản ứng quang hóa."},{"id":"qa21-g11-l4-s3-eeafe07039","title":"Màng thylakoid","takeaway":"Hệ sắc tố, các quang hệ và chuỗi truyền electron quang hợp nằm chủ yếu trên màng thylakoid."},{"id":"qa21-g11-l4-s3-cd9ecd655a","title":"Carotenoid","takeaway":"Carotenoid hấp thụ bổ sung ánh sáng và giúp bảo vệ hệ sắc tố trước ánh sáng mạnh."},{"id":"qa21-g11-l4-s4-94ffca2413","title":"ATP và NADPH","takeaway":"Pha sáng tạo ATP và NADPH dùng trong chu trình Calvin: ATP cung cấp năng lượng, NADPH cung cấp sức khử."},{"id":"qa21-g11-l4-s4-ff73e0065a","title":"Nguồn gốc O₂","takeaway":"Oxygen giải phóng trong quang hợp có nguồn gốc trực tiếp từ sự phân li nước ở quang hệ II."},{"id":"qa21-g11-l4-s4-f705afb757","title":"ATP synthase của lục lạp","takeaway":"Dòng proton theo gradient qua ATP synthase cung cấp năng lượng tổng hợp ATP."},{"id":"qa21-g11-l4-s5-d4659ed5df","title":"Chất nền lục lạp","takeaway":"Chu trình Calvin diễn ra trong chất nền lục lạp."},{"id":"qa21-g11-l4-s5-d9ea430286","title":"Không hiểu nhầm “pha tối”","takeaway":"Chu trình Calvin không trực tiếp dùng photon, nhưng không có nghĩa chỉ diễn ra ban đêm."},{"id":"qa21-g11-l4-s6-b609918667","title":"Chất nhận CO₂","takeaway":"RuBP là chất nhận CO₂ trong chu trình Calvin; RuBisCO xúc tác phản ứng gắn CO₂."},{"id":"qa21-g11-l4-s6-efaa4e221d","title":"Sản phẩm đầu ở cây C₃","takeaway":"Sản phẩm bền đầu tiên của cố định CO₂ ở cây C₃ là 3-phosphoglycerate, có 3 carbon."},{"id":"qa21-g11-l4-s6-be8b0484f4","title":"Tái sinh RuBP","takeaway":"Phần lớn G3P tạo trong chu trình Calvin được dùng để tái sinh RuBP, giúp chu trình tiếp tục."},{"id":"qa21-g11-l4-s7-86797c3c20","title":"Bước đầu con đường C₄","takeaway":"PEP là chất nhận carbon vô cơ ban đầu trong con đường C₄."},{"id":"qa21-g11-l4-s7-44ca45bc1f","title":"Tế bào bao bó mạch","takeaway":"Ở cây C₄ điển hình, chu trình Calvin chủ yếu diễn ra trong tế bào bao bó mạch."},{"id":"qa21-g11-l4-s7-daa9013752","title":"Oxaloacetate","takeaway":"PEP carboxylase tạo sản phẩm đầu tiên OAA có 4 carbon trong con đường C₄."},{"id":"qa21-g11-l4-s8-e9dd73ba25","title":"CAM thu CO₂ ban đêm","takeaway":"Cây CAM điển hình mở khí khổng, thu CO₂ và dự trữ dưới dạng acid hữu cơ chủ yếu vào ban đêm."},{"id":"qa21-g11-l4-s8-a964db580c","title":"C₄ khác CAM","takeaway":"C₄ tách hai bước cố định carbon theo không gian; CAM chủ yếu tách theo thời gian đêm–ngày."},{"id":"qa21-g11-l4-s9-d981fefb97","title":"C₄ và quang hô hấp","takeaway":"Con đường C₄ tập trung CO₂ gần RuBisCO, giúp hạn chế quang hô hấp."},{"id":"qa21-g11-l4-s9-7389240e01","title":"CAM và tiết kiệm nước","takeaway":"Thu CO₂ ban đêm giúp cây CAM giảm mất nước so với mở khí khổng khi ban ngày nóng, khô."},{"id":"qa21-g11-l4-s10-f1c10adcf0","title":"G3P làm nguyên liệu","takeaway":"G3P từ chu trình Calvin được dùng để tổng hợp đường và nhiều hợp chất hữu cơ."},{"id":"qa21-g11-l4-s11-c69d6a30fc","title":"Điểm bù ánh sáng","takeaway":"Tại điểm bù ánh sáng, quang hợp vừa bù lượng CO₂ thải do hô hấp nên trao đổi CO₂ ròng xấp xỉ 0."},{"id":"qa21-g11-l4-s11-da20072ac9","title":"Bão hòa ánh sáng","takeaway":"Sau điểm bão hòa ánh sáng, yếu tố khác giới hạn tốc độ; tăng ánh sáng không còn làm quang hợp tăng."},{"id":"qa21-g11-l4-s11-044d7d73ab","title":"Vùng ánh sáng hấp thụ","takeaway":"Diệp lục hấp thụ mạnh vùng đỏ và xanh tím; lá thường phản xạ nhiều ánh sáng lục."},{"id":"qa21-g11-l4-s12-dd9ec70172","title":"Nóng quá làm giảm quang hợp","takeaway":"Nhiệt độ quá cao ảnh hưởng enzyme, màng và trạng thái nước, có thể làm quang hợp giảm."},{"id":"qa21-g11-l4-s13-e7644cb7da","title":"CO₂ là yếu tố giới hạn","takeaway":"Khi CO₂ đang giới hạn, tăng CO₂ vừa phải thường làm quang hợp tăng cho tới khi yếu tố khác giới hạn."},{"id":"qa21-g11-l4-s13-92304f9d19","title":"Điểm bù CO₂","takeaway":"Điểm bù CO₂ là nồng độ tại đó lượng CO₂ hấp thụ và thải ra cân bằng."},{"id":"qa21-g11-l4-s14-3328c5eca4","title":"Diện tích lá và năng suất","takeaway":"Tăng diện tích lá không luôn tăng năng suất vì lá có thể che nhau và cạnh tranh nguồn lực."},{"id":"qa21-g11-l4-s14-310285e44b","title":"Chiếu sáng phù hợp","takeaway":"Đèn trồng cây cần cường độ, phổ sáng và thời gian chiếu phù hợp với loài, giai đoạn phát triển."},{"id":"qa21-g11-l5-s1-e0d47dc346","title":"Nhìn thấy lục lạp","takeaway":"Bào quan màu xanh thường thấy trong tế bào lá rong sống là lục lạp."},{"id":"qa21-g11-l5-s2-5946ae7382","title":"Chiết sắc tố","takeaway":"Ethanol hoặc acetone có thể chiết sắc tố lá vì sắc tố tan trong dung môi hữu cơ phù hợp."},{"id":"qa21-g11-l5-s2-6947ccf8f7","title":"Nguyên lí sắc kí","takeaway":"Sắc kí tách sắc tố do khác độ tan và mức tương tác với pha tĩnh, làm chúng di chuyển khác tốc độ."},{"id":"qa21-g11-l5-s3-295c44e08a","title":"Đặt cây trong tối","takeaway":"Đặt cây trong tối trước thí nghiệm tinh bột giúp giảm tinh bột đã tích lũy sẵn."},{"id":"qa21-g11-l5-s3-9165db3c0e","title":"Kiểm tra tinh bột ở lá","takeaway":"Phần lá được chiếu sáng đổi xanh đen với iodine gợi ý có tinh bột; cần so sánh với phần bị che và đối chứng."},{"id":"qa21-g11-l5-s3-11c9ad9c4b","title":"Tẩy màu lá","takeaway":"Tẩy bớt diệp lục bằng cồn giúp quan sát màu của phản ứng iodine–tinh bột rõ hơn."},{"id":"qa21-g11-l5-s4-631a8f2031","title":"Khí từ rong quang hợp","takeaway":"Khí làm que đóm còn tàn đỏ bùng sáng gợi ý oxygen; phép thử cần đủ khí và đối chứng."},{"id":"qa21-g11-l5-s4-8c9531eb36","title":"Đối chứng ánh sáng","takeaway":"Mẫu rong đặt trong tối giúp so sánh tác động của ánh sáng lên sự tạo khí quang hợp."},{"id":"qa21-g11-l6-s1-5b56ac186d","title":"Hô hấp tế bào thực vật","takeaway":"Hô hấp oxi hóa chất hữu cơ, chuyển một phần năng lượng vào ATP và phân tán một phần thành nhiệt."},{"id":"qa21-g11-l6-s1-7576654100","title":"Sản phẩm hô hấp hiếu khí","takeaway":"Hô hấp hiếu khí hoàn toàn glucose tạo CO₂, H₂O và giải phóng năng lượng."},{"id":"qa21-g11-l6-s2-6d1fb59a5b","title":"Chất trung gian của hô hấp","takeaway":"Ngoài ATP, hô hấp còn cung cấp các chất trung gian cho quá trình tổng hợp chất."},{"id":"qa21-g11-l6-s3-123d656aef","title":"Đường phân ở bào tương","takeaway":"Trong tế bào thực vật, đường phân diễn ra chủ yếu trong bào tương."},{"id":"qa21-g11-l6-s3-1a55d31530","title":"Chu trình Krebs","takeaway":"Ở tế bào thực vật, chu trình Krebs diễn ra chủ yếu trong chất nền ti thể."},{"id":"qa21-g11-l6-s3-d34ed719b6","title":"Vai trò oxygen","takeaway":"O₂ là chất nhận electron cuối cùng của chuỗi hô hấp hiếu khí và tham gia tạo nước."},{"id":"qa21-g11-l6-s4-e5c876e851","title":"ATP của đường phân – lên men","takeaway":"Một glucose qua đường phân và lên men thu ròng 2 ATP; bước lên men không trực tiếp tạo thêm ATP."},{"id":"qa21-g11-l6-s4-53e8a1632a","title":"Rễ thiếu oxygen","takeaway":"Rễ bị ngập có thể tăng lên men vì thiếu oxygen cho hô hấp hiếu khí."},{"id":"qa21-g11-l6-s5-07edb0dc9e","title":"Hạt hút nước","takeaway":"Hạt khô hút nước để nảy mầm thường tăng cường độ hô hấp do nhu cầu chuyển hóa tăng."},{"id":"qa21-g11-l6-s5-754a3c0685","title":"Nhiệt độ hô hấp thích hợp","takeaway":"Nhiệt độ hô hấp tối ưu phụ thuộc loài, cơ quan và trạng thái sinh lí, không có một mức chung cho mọi loài."},{"id":"qa21-g11-l6-s6-853051067c","title":"Bảo quản hạt khô","takeaway":"Phơi khô đúng mức giảm chuyển hóa của hạt và hoạt động vi sinh vật; mức làm khô phải phù hợp loại hạt."},{"id":"qa21-g11-l6-s6-cd307229dc","title":"Bảo quản lạnh","takeaway":"Lạnh thích hợp làm chậm hô hấp và quá trình gây hỏng rau quả; quá lạnh có thể gây tổn thương."},{"id":"qa21-g11-l6-s6-7ab1e7589b","title":"Đất thông thoáng","takeaway":"Làm đất thông thoáng tăng trao đổi khí, hỗ trợ hô hấp hiếu khí của rễ."},{"id":"qa21-g11-l6-s7-caab16093c","title":"Quang hợp nuôi hô hấp","takeaway":"Chất hữu cơ và O₂ do quang hợp tạo ra là nguyên liệu của hô hấp hiếu khí."},{"id":"qa21-g11-l6-s7-330d0b85dd","title":"Hô hấp cả ban ngày","takeaway":"Tế bào thực vật còn sống vẫn hô hấp ban ngày; quang hợp không thay thế nhu cầu hô hấp."},{"id":"qa21-g11-l7-s1-fe0f9657d0","title":"Phát hiện CO₂ từ hạt","takeaway":"CO₂ từ hạt nảy mầm có thể làm nước vôi trong vẩn đục do tạo kết tủa calcium carbonate."},{"id":"qa21-g11-l7-s2-fcf6478e5d","title":"Đối chứng hô hấp hạt","takeaway":"Chuông có nước vôi nhưng không có hạt nảy mầm giúp đối chiếu nguồn CO₂ không do hạt."},{"id":"qa21-g11-l8-s1-772e830d52","title":"Ăn lọc","takeaway":"Trai giữ lại các hạt thức ăn lơ lửng khi nước đi qua bộ phận lọc: đó là ăn lọc."},{"id":"qa21-g11-l8-s1-d7f8bec579","title":"Ăn hút","takeaway":"Rệp dùng vòi lấy dịch cây là ví dụ ăn hút."},{"id":"qa21-g11-l8-s2-fb6d7356ce","title":"Tiêu hóa nội bào","takeaway":"Tiêu hóa nội bào là phân giải thức ăn bên trong các khoang tiêu hóa của tế bào."},{"id":"qa21-g11-l8-s2-234c0add2d","title":"Tiêu hóa ở thủy tức","takeaway":"Thủy tức tiêu hóa ngoại bào trước trong túi tiêu hóa, rồi tiếp tục tiêu hóa nội bào."},{"id":"qa21-g11-l8-s2-4a50bd3ebc","title":"Amylase nước bọt","takeaway":"Amylase bắt đầu phân giải tinh bột trong miệng người."},{"id":"qa21-g11-l8-s2-6d71723922","title":"Pepsin khác HCl","takeaway":"Pepsin xúc tác phân giải protein ở dạ dày; HCl tạo môi trường acid, không phải enzyme."},{"id":"qa21-g11-l8-s2-b4439f21b2","title":"Muối mật","takeaway":"Muối mật nhũ tương hóa chất béo thành giọt nhỏ để lipase hoạt động hiệu quả hơn."},{"id":"qa21-g11-l8-s2-ec687f8b56","title":"Nhu động","takeaway":"Nhu động ống tiêu hóa giúp đẩy và trộn thức ăn với dịch tiêu hóa."},{"id":"qa21-g11-l8-s3-cab14549c1","title":"Ruột non","takeaway":"Ruột non hấp thụ phần lớn chất dinh dưỡng đã tiêu hóa ở người."},{"id":"qa21-g11-l8-s3-bd51df0f27","title":"Tăng diện tích hấp thụ","takeaway":"Lông ruột và vi nhung mao làm tăng diện tích hấp thụ của biểu mô ruột."},{"id":"qa21-g11-l8-s4-a1657490a1","title":"Đồng hóa sau hấp thụ","takeaway":"Tổng hợp protein cơ thể từ amino acid đã hấp thụ là đồng hóa."},{"id":"qa21-g11-l8-s5-426fda6c4a","title":"Nhu cầu năng lượng","takeaway":"Hai người khác mức vận động có thể cần lượng năng lượng khác nhau; tuổi, kích thước và trạng thái sinh lí cũng ảnh hưởng."},{"id":"qa21-g11-l8-s6-0e7c67870a","title":"An toàn thực phẩm","takeaway":"Thực phẩm an toàn giúp giảm đưa mầm bệnh và chất độc vào cơ thể."},{"id":"qa21-g11-l8-s7-fabc037e27","title":"Phòng bệnh tiêu hóa","takeaway":"Rửa tay và dùng nước, thực phẩm an toàn giúp hạn chế bệnh lây qua đường tiêu hóa."},{"id":"qa21-g11-l9-s1-730e1d01de","title":"Hô hấp tế bào khác thông khí","takeaway":"Thông khí là chuyển động không khí; hô hấp tế bào phân giải chất để tạo ATP."},{"id":"qa21-g11-l9-s2-4f705add20","title":"Hệ hô hấp cung cấp O₂","takeaway":"Hệ hô hấp cung cấp oxygen để hỗ trợ hô hấp hiếu khí trong tế bào."},{"id":"qa21-g11-l9-s3-8ff1364c3e","title":"Trao đổi khí qua da","takeaway":"Bề mặt trao đổi khí qua da hiệu quả thường mỏng và ẩm."},{"id":"qa21-g11-l9-s4-1aa1836f3a","title":"Hệ ống khí côn trùng","takeaway":"Ở đa số côn trùng, ống khí đưa O₂ trực tiếp tới mô và tế bào."},{"id":"qa21-g11-l9-s5-957afce27e","title":"Dòng ngược chiều ở mang","takeaway":"Máu và nước chảy ngược chiều ở mang cá điển hình, giúp duy trì chênh lệch phân áp O₂."},{"id":"qa21-g11-l9-s6-c8f4cbddb9","title":"Phế nang","takeaway":"Phế nang là nơi trao đổi khí chủ yếu trong phổi người."},{"id":"qa21-g11-l9-s6-7d2cde2236","title":"Cơ hoành khi hít vào","takeaway":"Khi hít vào bình thường, cơ hoành co và hạ xuống, tăng thể tích lồng ngực."},{"id":"qa21-g11-l9-s6-a35106cd7c","title":"Túi khí ở chim","takeaway":"Túi khí chủ yếu hỗ trợ thông khí qua phổi; trao đổi khí chủ yếu diễn ra tại phổi."},{"id":"qa21-g11-l9-s7-80132b207c","title":"Khói thuốc và đường thở","takeaway":"Tránh khói thuốc giúp giảm tiếp xúc với các chất gây hại cho đường thở."},{"id":"qa21-g11-l10-s1-d46127da94","title":"Định nghĩa động mạch","takeaway":"Động mạch đưa máu rời tim; tên gọi dựa vào hướng dòng máu, không dựa vào lượng oxygen."},{"id":"qa21-g11-l10-s2-7d0830ea69","title":"Tuần hoàn kín","takeaway":"Trong hệ tuần hoàn kín, máu lưu thông trong hệ mạch và trao đổi với dịch mô qua thành mạch nhỏ."},{"id":"qa21-g11-l10-s2-ae128b12e2","title":"Tuần hoàn kép","takeaway":"Trong một vòng tuần hoàn kép hoàn chỉnh, máu đi qua tim hai lần: vòng phổi và vòng cơ thể."},{"id":"qa21-g11-l10-s3-5fbda6f06c","title":"Nút xoang nhĩ","takeaway":"Nút xoang nhĩ là bộ phận phát nhịp bình thường của tim người."},{"id":"qa21-g11-l10-s3-52bc0d7983","title":"Thành thất trái","takeaway":"Thất trái có thành dày hơn thất phải vì cần tạo áp lực lớn hơn cho vòng tuần hoàn cơ thể."},{"id":"qa21-g11-l10-s3-c84e4c9ef9","title":"Đóng van nhĩ–thất","takeaway":"Van nhĩ–thất đóng khi áp suất thất cao hơn áp suất nhĩ, hạn chế máu chảy ngược lên nhĩ."},{"id":"qa21-g11-l10-s3-8c22ae23ff","title":"Ví dụ chu kì tim","takeaway":"Tim đập 75 nhịp/phút thì mỗi chu kì dài 60/75 = 0,8 giây; đây không phải hằng số cho mọi người."},{"id":"qa21-g11-l10-s4-fd675d20d1","title":"Máu chảy chậm ở mao mạch","takeaway":"Tổng tiết diện mạng mao mạch rất lớn nên vận tốc máu trung bình thấp."},{"id":"qa21-g11-l10-s4-e0d42cf02b","title":"Huyết áp tâm thu","takeaway":"Huyết áp tâm thu là áp suất động mạch cao nhất trong chu kì tim."},{"id":"qa21-g11-l10-s5-bbbf9d3910","title":"Phản xạ khi huyết áp giảm","takeaway":"Khi huyết áp giảm đột ngột, phản xạ điều hòa thường tăng nhịp và lực co tim."},{"id":"qa21-g11-l10-s6-4757707fe7","title":"Nhịp nghỉ của người tập sức bền","takeaway":"Thể tích tâm thu lớn hơn có thể bù nhịp nghỉ thấp để duy trì cung lượng tim."},{"id":"qa21-g11-l11-s1-505ae4025f","title":"Quy đổi nhịp mạch","takeaway":"Đếm 36 nhịp trong 30 giây tương ứng khoảng 72 nhịp/phút, với giả thiết nhịp đều khi đo."},{"id":"qa21-g11-l11-s2-af23d1a4d4","title":"Chuẩn hóa đo huyết áp","takeaway":"Nghỉ yên trước khi đo giúp hạn chế ảnh hưởng tức thời của vận động khi so sánh huyết áp nghỉ."},{"id":"qa21-g11-l11-s3-18eb2c29c3","title":"Tính tự động của tim","takeaway":"Tim cô lập còn đập trong điều kiện thích hợp cho thấy tim có khả năng phát nhịp tự động."},{"id":"qa21-g11-l11-s4-2569cb8001","title":"Đối giao cảm","takeaway":"Kích thích sợi đối giao cảm đến tim thường làm nhịp tim giảm."},{"id":"qa21-g11-l11-s5-363a9d735b","title":"Adrenalin","takeaway":"Adrenalin thường làm tăng nhịp và lực co tim qua tác động thể dịch."},{"id":"qa21-g11-l12-s1-8b4c9bb986","title":"Nguyên nhân bên trong","takeaway":"Bệnh do đột biến di truyền có nguyên nhân bên trong cơ thể, không chỉ do tác nhân bên ngoài."},{"id":"qa21-g11-l12-s2-3676850269","title":"Virus cần tế bào chủ","takeaway":"Virus phụ thuộc hệ thống tế bào chủ để tạo thế hệ virus mới."},{"id":"qa21-g11-l12-s3-c5af934280","title":"Tia tử ngoại và DNA","takeaway":"Tia tử ngoại có thể gây tổn thương DNA; sửa chữa không đúng có thể tạo đột biến liên quan ung thư da."},{"id":"qa21-g11-l12-s4-9c23f2216c","title":"Cyanide và hô hấp tế bào","takeaway":"Cyanide cản trở sử dụng O₂ trong hô hấp tế bào bằng cách ức chế cytochrome c oxidase."},{"id":"qa21-g11-l12-s6-f091bf7efc","title":"Hệ miễn dịch","takeaway":"Hệ miễn dịch phối hợp hàng rào, tế bào và phân tử để nhận diện, chống tác nhân gây hại."},{"id":"qa21-g11-l12-s7-fff0f4c8ea","title":"Hàng rào da","takeaway":"Da nguyên vẹn là hàng rào miễn dịch bẩm sinh, giúp cản tác nhân xâm nhập."},{"id":"qa21-g11-l12-s7-0f023cd644","title":"Đại thực bào","takeaway":"Đại thực bào bao lấy và phân giải nhiều tác nhân qua quá trình thực bào."},{"id":"qa21-g11-l12-s8-f306dcf85c","title":"Miễn dịch thích ứng","takeaway":"Tính đặc hiệu và trí nhớ là hai đặc điểm nổi bật của miễn dịch thích ứng."},{"id":"qa21-g11-l12-s9-9088d71ba4","title":"Epitope","takeaway":"Epitope là phần cụ thể của kháng nguyên được kháng thể hoặc thụ thể nhận diện đặc hiệu."},{"id":"qa21-g11-l12-s10-fd51686cf9","title":"Thụ thể tế bào B","takeaway":"Thụ thể trên tế bào B nhận diện kháng nguyên phù hợp."},{"id":"qa21-g11-l12-s11-f487c7ca4f","title":"Tương bào","takeaway":"Tế bào B hoạt hóa có thể biệt hóa thành tương bào tiết nhiều kháng thể."},{"id":"qa21-g11-l12-s12-070bfb110c","title":"Miễn dịch dịch thể","takeaway":"Miễn dịch dịch thể dựa chủ yếu vào kháng thể trong dịch cơ thể."},{"id":"qa21-g11-l12-s12-4691361591","title":"Tế bào T độc","takeaway":"Tế bào T độc có thể nhận diện và gây chết tế bào nhiễm virus."},{"id":"qa21-g11-l12-s13-521dd884af","title":"Tế bào nhớ","takeaway":"Tế bào nhớ giúp đáp ứng với cùng kháng nguyên ở lần sau thường nhanh hơn."},{"id":"qa21-g11-l12-s13-1d8dc2a92f","title":"Vaccine","takeaway":"Vaccine giúp tạo đáp ứng và trí nhớ miễn dịch; không đồng nghĩa bảo vệ tuyệt đối."},{"id":"qa21-g11-l12-s14-7fdf45a643","title":"Dị ứng","takeaway":"Dị ứng là đáp ứng quá mẫn với dị nguyên; tác nhân và mức độ khác nhau giữa người."},{"id":"qa21-g11-l12-s15-488921bf8a","title":"HIV và T CD4","takeaway":"HIV gây suy giảm miễn dịch chủ yếu liên quan đến tổn thương tế bào T CD4."},{"id":"qa21-g11-l12-s16-a805c05565","title":"Di căn","takeaway":"Di căn là hiện tượng tế bào ung thư lan và phát triển ở vị trí khác trong cơ thể."},{"id":"qa21-g11-l12-s17-cb0d8b4ae4","title":"Tự miễn","takeaway":"Trong bệnh tự miễn, hệ miễn dịch tấn công thành phần của chính cơ thể."},{"id":"qa21-g11-l12-s17-401a0fe86e","title":"Đái tháo đường type 1","takeaway":"Ở type 1 điển hình, tự miễn phá hủy tế bào β tuyến tụy, làm thiếu insulin."},{"id":"qa21-g11-l13-s1-3542bf559e","title":"Thải CO₂ là bài tiết","takeaway":"Thải CO₂ qua phổi là bài tiết vì CO₂ là sản phẩm chuyển hóa."},{"id":"qa21-g11-l13-s1-b36fc4595a","title":"Bài tiết bảo vệ nội môi","takeaway":"Loại bỏ chất thải chuyển hóa góp phần giữ thành phần dịch cơ thể trong khoảng phù hợp."},{"id":"qa21-g11-l13-s2-a65c081b5e","title":"Nephron","takeaway":"Nephron là đơn vị cấu tạo và chức năng cơ bản của thận, gồm tiểu thể thận và ống thận."},{"id":"qa21-g11-l13-s2-3433634a11","title":"Niệu quản khác niệu đạo","takeaway":"Niệu quản dẫn nước tiểu từ thận đến bàng quang; niệu đạo dẫn từ bàng quang ra ngoài."},{"id":"qa21-g11-l13-s3-dd14bd75f5","title":"Lọc ở cầu thận","takeaway":"Lọc đưa nước và chất nhỏ từ mao mạch cầu thận vào nang Bowman, giữ lại tế bào máu và phần lớn protein lớn."},{"id":"qa21-g11-l13-s3-77d6e65333","title":"Tái hấp thụ","takeaway":"Glucose từ dịch ống thận trở về máu là tái hấp thụ."},{"id":"qa21-g11-l13-s3-2094d510a5","title":"Bài tiết ở ống thận","takeaway":"Chuyển chất từ máu vào lòng ống thận sau lọc là bài tiết ở ống thận."},{"id":"qa21-g11-l13-s4-23016ecead","title":"Ổn định động","takeaway":"Cân bằng nội môi là duy trì chỉ số trong khoảng được điều hòa, không cố định tuyệt đối."},{"id":"qa21-g11-l13-s4-9c2866d6e8","title":"Thụ thể nội môi","takeaway":"Thụ thể phát hiện thay đổi và cung cấp thông tin cho bộ phận điều khiển."},{"id":"qa21-g11-l13-s5-d8065cb7a7","title":"ADH giữ nước","takeaway":"ADH làm tăng tái hấp thụ nước ở ống góp, thường làm giảm lượng nước tiểu."},{"id":"qa21-g11-l13-s5-3d4c86407b","title":"Insulin","takeaway":"Insulin hỗ trợ thu nhận, sử dụng và dự trữ glucose, làm hạ glucose máu."},{"id":"qa21-g11-l13-s5-ea0b740b24","title":"Phổi và pH máu","takeaway":"Phổi góp phần điều hòa pH máu bằng điều chỉnh lượng CO₂ thải ra."},{"id":"qa21-g11-l13-s6-264a0c0915","title":"Nhu cầu nước không cố định","takeaway":"Nhu cầu nước phụ thuộc hoạt động, điều kiện và sức khỏe; không giống nhau ở mọi người."},{"id":"qa21-g11-l13-s7-3c1e0e54d5","title":"Sỏi và dòng nước tiểu","takeaway":"Sỏi tiết niệu có thể cản trở dòng nước tiểu, gây tổn thương hoặc thuận lợi cho nhiễm trùng."},{"id":"qa21-g11-l13-s8-8e38366318","title":"Hiểu kết quả xét nghiệm","takeaway":"Một kết quả bất thường không đủ để tự kết luận bệnh; cần bối cảnh và đánh giá chuyên môn."},{"id":"qa21-g11-l14-s1-cdf9b8f63f","title":"Cảm ứng ở cây","takeaway":"Cụp lá khi bị chạm ở cây trinh nữ là cảm ứng: nhận kích thích cơ học và tạo đáp ứng."},{"id":"qa21-g11-l14-s2-d76a70ef13","title":"Ba bước cảm ứng","takeaway":"Đáp ứng cảm ứng có trình tự khái quát: tiếp nhận → xử lí → đáp ứng."},{"id":"qa21-g11-l15-s1-9e91ea77d7","title":"Cảm ứng nhanh và chậm","takeaway":"Không phải mọi cảm ứng ở thực vật đều chậm; cụp lá trinh nữ là ví dụ nhanh."},{"id":"qa21-g11-l15-s2-b54e583d6f","title":"Hướng sáng dương","takeaway":"Thân non mọc về phía ánh sáng là hướng sáng dương."},{"id":"qa21-g11-l15-s2-ea849b4df8","title":"Ứng động khác hướng động","takeaway":"Hướng đáp ứng của ứng động không phụ thuộc hướng kích thích, khác hướng động."},{"id":"qa21-g11-l15-s2-a2bed6b59c","title":"Hướng tiếp xúc","takeaway":"Tua cuốn quấn quanh giá đỡ là hướng tiếp xúc."},{"id":"qa21-g11-l15-s3-6cbf4e0fdb","title":"Auxin và thân hướng sáng","takeaway":"Ở thân non hướng sáng, phía khuất sáng thường dãn dài mạnh hơn làm thân cong về phía sáng."},{"id":"qa21-g11-l15-s3-f755b8c02b","title":"Thể gối của trinh nữ","takeaway":"Cụp lá nhanh ở trinh nữ chủ yếu do thay đổi sức trương ở thể gối."},{"id":"qa21-g11-l15-s4-a17cba1a77","title":"Ứng dụng làm giàn","takeaway":"Làm giàn cho cây có tua cuốn tận dụng phản ứng hướng tiếp xúc."},{"id":"qa21-g11-l16-s1-a1cdf59179","title":"Thử hướng sáng","takeaway":"Để kiểm tra hướng sáng của thân non, đổi hướng chiếu sáng và giữ các yếu tố khác tương đương."},{"id":"qa21-g11-l16-s2-77ec233d5d","title":"Rễ và trọng lực","takeaway":"Rễ ngô vẫn mọc xuống khi hạt đặt ngược là ví dụ hướng trọng lực dương."},{"id":"qa21-g11-l16-s3-e1d41f35d9","title":"Hướng hóa","takeaway":"Rễ phát triển về vùng khoáng thích hợp là hướng hóa dương; nồng độ quá cao có thể gây hại."},{"id":"qa21-g11-l16-s4-7b008e1acc","title":"Phân loại vận động cây","takeaway":"Muốn phân loại vận động cây, cần xác định tác nhân và so sánh hướng đáp ứng với hướng tác nhân."},{"id":"qa21-g11-l17-s1-2ee9c70cb1","title":"Thần kinh trung ương","takeaway":"Hệ thần kinh trung ương ở người gồm não và tủy sống."},{"id":"qa21-g11-l17-s1-05cadcad95","title":"Thần kinh dạng lưới","takeaway":"Thủy tức có hệ thần kinh dạng lưới, cho phép kích thích lan rộng trong cơ thể."},{"id":"qa21-g11-l17-s2-017af30d03","title":"Sợi trục","takeaway":"Sợi trục neuron thường dẫn tín hiệu tới các tế bào khác."},{"id":"qa21-g11-l17-s2-cbc93b6125","title":"Điện thế nghỉ","takeaway":"Ở neuron nghỉ điển hình, phía trong màng âm hơn phía ngoài."},{"id":"qa21-g11-l17-s2-427c0cab9b","title":"Khử cực neuron","takeaway":"Pha khử cực nhanh thường do Na⁺ đi vào qua kênh Na⁺ phụ thuộc điện thế."},{"id":"qa21-g11-l17-s2-0494277d71","title":"Myelin và dẫn truyền","takeaway":"Bao myelin giúp dẫn truyền nhanh nhờ điện thế hoạt động được tái tạo tại các eo Ranvier."},{"id":"qa21-g11-l17-s3-c351859081","title":"Ca²⁺ trước synapse","takeaway":"Ca²⁺ đi vào tận cùng trước synapse kích thích túi synapse giải phóng chất dẫn truyền."},{"id":"qa21-g11-l17-s3-2ca45bffde","title":"Màng sau synapse","takeaway":"Chất dẫn truyền gắn thụ thể màng sau synapse, có thể gây kích thích hoặc ức chế."},{"id":"qa21-g11-l17-s4-2225690c20","title":"Đường hướng tâm","takeaway":"Đường hướng tâm dẫn tín hiệu từ thụ thể về trung ương thần kinh."},{"id":"qa21-g11-l17-s4-c43b3b629e","title":"Phản xạ rút tay","takeaway":"Phản xạ rút tay nhanh khi chạm vật nhọn có thể được tích hợp chủ yếu ở tủy sống."},{"id":"qa21-g11-l17-s4-8b7876d968","title":"Tế bào que và nón","takeaway":"Tế bào que và nón ở võng mạc trực tiếp tiếp nhận ánh sáng."},{"id":"qa21-g11-l17-s4-7daa9a6c64","title":"Hệ tiền đình","takeaway":"Hệ tiền đình ở tai trong tham gia giữ thăng bằng; ốc tai chuyên về nghe."},{"id":"qa21-g11-l17-s4-c9d7bdb574","title":"Điều kiện hóa đáp ứng","takeaway":"Chó tiết nước bọt khi nghe âm từng đi trước thức ăn là điều kiện hóa đáp ứng."},{"id":"qa21-g11-l17-s5-0fc75da9ea","title":"Cơ chế thuốc tê","takeaway":"Thuốc tê chẹn kênh Na⁺, cản trở lan truyền điện thế hoạt động ở sợi cảm giác."},{"id":"qa21-g11-l17-s6-5b6d470174","title":"Gây nghiện không đồng nghĩa kích thích","takeaway":"Có chất gây nghiện gây ức chế thần kinh; không thể xếp tất cả vào nhóm kích thích."},{"id":"qa21-g11-l18-s4-40ffccde80","title":"Pheromone","takeaway":"Pheromone truyền tín hiệu chủ yếu giữa các cá thể cùng loài qua môi trường."},{"id":"qa21-g11-l18-s5-13ee846344","title":"Học không gian","takeaway":"Động vật ghi nhớ vị trí, đường đi và nơi có thức ăn là học nhận biết không gian."},{"id":"qa21-g11-l20-s6-0f6c0b0c56","title":"Quang chu kì","takeaway":"Độ dài tương đối ngày và đêm ảnh hưởng ra hoa ở loài nhạy quang chu kì."},{"id":"qa21-g11-l25-s2-5308ccc2a8","title":"Tạo hợp tử ở thực vật có hoa","takeaway":"Một tinh tử kết hợp với trứng tạo hợp tử; hợp tử phát triển thành phôi."},{"id":"qa21-g11-l27-s2-3f26adbba5","title":"Thụ tinh ở người","takeaway":"Tinh trùng kết hợp với tế bào trứng tạo hợp tử, mở đầu phát triển cơ thể mới."},{"id":"qa21-g11-l27-s3-984fe9887c","title":"Thụ tinh nhân tạo trong chăn nuôi","takeaway":"Thụ tinh nhân tạo hỗ trợ đưa tinh dịch vào đường sinh dục con cái; không phải nhân bản hay chỉnh sửa gene."},{"id":"qa21-g11-l31-s0-fe98842e2d","title":"Tuần hoàn đơn của cá","takeaway":"Ở cá có tuần hoàn đơn điển hình, máu từ tim đến mang trước, rồi đến cơ quan và trở về tim."},{"id":"qa21-g11-l31-s0-4fd21df382","title":"Ưu thế tuần hoàn kép","takeaway":"Tim tạo lại áp lực sau vòng trao đổi khí, rồi bơm máu vào vòng cơ thể ở áp lực phù hợp."},{"id":"qa21-g11-l31-s1-f2cb598217","title":"Máu từ phổi về tim","takeaway":"Máu từ phổi trở về tâm nhĩ trái qua tĩnh mạch phổi."},{"id":"qa21-g11-l31-s1-14cb29717e","title":"Nuôi cơ tim","takeaway":"Động mạch vành cung cấp máu nuôi chính cơ tim."},{"id":"qa21-g11-l31-s2-fb251be97a","title":"Ví dụ cung lượng tim","takeaway":"Nhịp 72 lần/phút × thể tích tâm thu 70 mL = 5.040 mL/phút = 5,04 L/phút."},{"id":"qa21-g11-l31-s2-85440ca4b3","title":"Hai tâm thất bơm bằng nhau","takeaway":"Ở trạng thái ổn định, lượng máu hai tâm thất bơm trong một phút xấp xỉ bằng nhau."},{"id":"qa21-g11-l31-s3-5eb6de6050","title":"Van khi co đẳng tích","takeaway":"Trong pha co đẳng tích tâm thất, van nhĩ–thất và van bán nguyệt đều đóng."},{"id":"qa21-g11-l31-s3-f92cb7c3e6","title":"Mở van động mạch chủ","takeaway":"Van động mạch chủ mở khi áp suất thất trái vượt áp suất động mạch chủ."},{"id":"qa21-g11-l31-s4-b5dc347213","title":"Tiếng tim S2","takeaway":"Tiếng tim thứ hai S2 chủ yếu liên quan đến đóng các van bán nguyệt."},{"id":"qa21-g11-l31-s4-ef3e3d7570","title":"Điện tâm đồ","takeaway":"Điện tâm đồ ghi biến đổi điện thế liên quan hoạt động tim, không đo trực tiếp lực co hay thể tích tim."},{"id":"qa21-g11-l31-s5-adb1a58276","title":"Đàn hồi động mạch","takeaway":"Thành động mạch lớn dãn khi nhận máu và đàn hồi trở lại, giúp duy trì dòng máu giữa các nhịp tống."},{"id":"qa21-g11-l31-s5-5b2eaa4ec0","title":"Van tĩnh mạch","takeaway":"Van ở nhiều tĩnh mạch chi hạn chế máu chảy ngược và hỗ trợ máu về tim cùng co cơ xương."},{"id":"qa21-g11-l31-s6-4abd9f0058","title":"Co tiểu động mạch","takeaway":"Cơ trơn tiểu động mạch co làm giảm đường kính lòng mạch và tăng sức cản."},{"id":"qa21-g11-l31-s6-399b296d94","title":"Trao đổi O₂ với mô","takeaway":"O₂ đi từ máu mao mạch vào mô chủ yếu bằng khuếch tán theo chênh lệch phân áp."},{"id":"qa21-g11-l31-s7-7d4e63975e","title":"Dẫn lưu bạch huyết","takeaway":"Hệ bạch huyết đưa dịch và protein từ mô trở lại tuần hoàn máu."},{"id":"qa21-g11-l31-s7-9441f4c1a0","title":"Hạch bạch huyết","takeaway":"Hạch lọc bạch huyết và hỗ trợ đáp ứng miễn dịch với kháng nguyên."},{"id":"qa21-g11-l31-s11-650e5135d7","title":"Thời kì trơ tuyệt đối","takeaway":"Trong thời kì trơ tuyệt đối, kích thích thêm không gây điện thế hoạt động tim mới."},{"id":"qa21-g11-l31-s13-3899f8db06","title":"Tưới máu thận giảm","takeaway":"Tưới máu thận giảm mạnh vượt khả năng tự điều hòa thường làm lọc cầu thận giảm."},{"id":"qa21-g11-l31-s14-99c8d4dc1a","title":"Ví dụ bán kính và sức cản","takeaway":"Theo mô hình Poiseuille, giảm bán kính còn 0,8 lần làm sức cản tăng 1/0,8⁴ ≈ 2,44 lần nếu các yếu tố khác giữ nguyên."},{"id":"qa21-g11-l31-s14-374299a78d","title":"Độ nhớt và lưu lượng","takeaway":"Trong mô hình Poiseuille, tăng độ nhớt làm lưu lượng giảm khi giữ chênh áp và kích thước ống không đổi."},{"id":"qa21-g11-l31-s15-1464dee90d","title":"Nhận diện co đẳng tích","takeaway":"Co đẳng tích là pha áp suất thất tăng trong khi thể tích thất gần như không đổi."},{"id":"qa21-g11-l31-s16-7d9cb6db31","title":"Thông liên nhĩ","takeaway":"Thông liên nhĩ là có lỗ thông ở vách giữa hai tâm nhĩ, không phải bất thường “van liên nhĩ”."},{"id":"qa21-g11-l31-s17-ebba4b1525","title":"Nhân hai tỉ lệ tăng","takeaway":"Nhịp tăng 40% và thể tích tâm thu tăng 70% làm cung lượng tim thành 1,40 × 1,70 = 2,38 lần cũ."},{"id":"qa21-g11-l31-s18-e374a55d7e","title":"Từ chu kì đến cung lượng","takeaway":"Chu kì 0,8 giây và thể tích tâm thu 70 mL cho nhịp 75 lần/phút, cung lượng 5,25 L/phút."},{"id":"qa21-g11-l31-s19-febb76943b","title":"Tính sức cản","takeaway":"Với ΔP = 10 mmHg và Q = 5 L/phút: R = ΔP/Q = 2 mmHg·phút/L."},{"id":"qa21-g11-l31-s20-b518c07bfc","title":"Dãn đẳng tích","takeaway":"Trong pha dãn đẳng tích, áp suất thất giảm nhưng thể tích gần như không đổi vì các van vẫn đóng."},{"id":"qa21-g11-l31-s21-68bcb39e0e","title":"Hẹp van động mạch chủ","takeaway":"Hẹp van động mạch chủ trực tiếp cản dòng máu từ thất trái vào động mạch chủ."},{"id":"qa21-g11-l31-s22-9d58846085","title":"Giảm sức co bóp","takeaway":"Khi tiền gánh và hậu gánh không đổi, giảm sức co bóp thường làm thể tích cuối tâm thu tăng."},{"id":"qa21-g11-l31-s23-650dbe2a48","title":"Hở van hai lá","takeaway":"Khi thất co, hở van hai lá cho phép máu trào ngược từ thất trái lên nhĩ trái."},{"id":"qa21-g11-l31-s23-bdb03da4ab","title":"Hở van động mạch chủ","takeaway":"Khi tâm trương, hở van động mạch chủ cho phép máu trào ngược từ động mạch chủ vào thất trái."},{"id":"qa21-g11-l31-s24-e59de4e814","title":"Hẹp van hai lá","takeaway":"Hẹp van hai lá cản trở dòng máu từ nhĩ trái xuống thất trái."},{"id":"qa21-g11-l31-s26-250db480ed","title":"Nhịp và thời gian chu kì","takeaway":"Khi đối giao cảm làm nhịp tim giảm, khoảng thời gian giữa hai nhịp tăng."},{"id":"qa21-g11-l31-s27-755a04fc5a","title":"Hai tiếng tim cơ bản","takeaway":"S1 chủ yếu do van nhĩ–thất đóng; S2 chủ yếu do van bán nguyệt đóng."},{"id":"qa21-g11-l31-s28-5030ad29a5","title":"Khoảng R–R","takeaway":"Trên ECG nhịp đều, khoảng R–R ngắn lại cho biết nhịp tim tăng."},{"id":"qa21-g11-l31-s28-c772557836","title":"ANP","takeaway":"ANP có xu hướng tăng thải Na⁺ và nước ở thận, góp phần giảm thể tích dịch tuần hoàn."},{"id":"qa21-g11-l31-s29-98da19a0ab","title":"Đóng góp của nhĩ co","takeaway":"Giảm sức co tâm nhĩ trực tiếp làm giảm phần đổ đầy thất do nhĩ co vào cuối tâm trương."},{"id":"qa21-g11-l31-s30-38239534a0","title":"Phân suất tống máu","takeaway":"EDV 70 µL và ESV 30 µL cho EF = (70 − 30)/70 × 100 ≈ 57,1%."},{"id":"qa21-g11-l31-s30-73f22888ef","title":"Đổi đơn vị cung lượng","takeaway":"Thể tích tâm thu 40 µL × nhịp 450/phút = 18.000 µL/phút = 18 mL/phút."},{"id":"qa21-g11-l32-s1-aeb2a2236a","title":"Từ dạ dày đến ruột","takeaway":"Theo đường đi bình thường, thức ăn rời dạ dày qua môn vị đến tá tràng, phần đầu ruột non."},{"id":"qa21-g11-l34-s1-3299ae89cf","title":"Thông khí phế nang","takeaway":"Khí lưu thông 0,5 L, khoảng chết 0,15 L, nhịp 10/phút cho thông khí phế nang (0,5 − 0,15) × 10 = 3,5 L/phút."},{"id":"qa21-g11-l34-s1-df6f24294c","title":"Thở ra lúc nghỉ","takeaway":"Thở ra bình thường lúc nghỉ ở người khỏe mạnh chủ yếu thụ động nhờ đàn hồi phổi–lồng ngực."},{"id":"qa21-g11-l36-s1-16eccb0da1","title":"Đỉnh LH","takeaway":"Đợt tăng mạnh LH thường kích hoạt rụng trứng; không có một ngày cố định cho mọi chu kì."},{"id":"qa21-g11-l38-s1-06d655a5b5","title":"Lan truyền điện thế hoạt động","takeaway":"Trên sợi trục khỏe, điện thế hoạt động được tái tạo dọc màng, không tự giảm biên độ như điện thế thụ động."},{"id":"qa21-g11-l38-s2-bf176db6ad","title":"Giao thoa thị giác","takeaway":"Tổn thương trung tâm giao thoa thị giác thường làm mất hai nửa thị trường phía thái dương."},{"id":"qa21-g11-l39-s1-1109b3dae4","title":"Cortisol phản hồi âm","takeaway":"Cortisol tăng kéo dài thường ức chế tiết ACTH qua phản hồi âm."},{"id":"qa21-g11-l40-s1-b43b906489","title":"Hai tác động của muối","takeaway":"NaCl ngoài rễ tăng cao có thể gây cả stress thẩm thấu và stress ion."},{"id":"qa21-g11-l40-s2-1af4faed6a","title":"Vi sợi cellulose và dãn dài","takeaway":"Vi sợi cellulose xếp chủ yếu theo vòng ngang thường thuận lợi cho tế bào kéo dài dọc trục khi điều kiện thích hợp."},{"id":"qa21-g11-l41-s1-a1ea94e050","title":"Đai Caspary","takeaway":"Đai Caspary cản con đường gian bào ở nội bì rễ, buộc nước và chất tan đi qua màng trước khi vào trung trụ."},{"id":"qa21-g11-l41-s1-c3f51d2245","title":"Cầu sinh chất","takeaway":"Cầu sinh chất nối tế bào chất các tế bào rễ kề nhau, tạo con đường vận chuyển tế bào chất."},{"id":"qa21-g11-l42-s1-b052f881f7","title":"Nitrate hóa trong hồ cá","takeaway":"Lọc sinh học có thể chuyển ammonium → nitrite → nitrate nhờ vi sinh vật nitrate hóa và oxygen."},{"id":"qa21-g11-l42-s2-7b013263ab","title":"Tính nitrogen trong phân","takeaway":"Phân urea chứa 46% N theo khối lượng: 10 kg phân cung cấp 10 × 0,46 = 4,6 kg N."},{"id":"qa21-g11-l43-s2-fe8564939c","title":"Acid ở cây CAM","takeaway":"Ở cây CAM điển hình, acid hữu cơ trong không bào thường tích lũy nhiều nhất vào cuối đêm."},{"id":"qa21-g11-l43-s3-fe505a5656","title":"Khởi đầu hô hấp sáng","takeaway":"Hô hấp sáng khởi đầu khi RuBisCO gắn O₂ vào RuBP."},{"id":"qa21-g12-l1-s1-9bfb17e608","title":"Đơn phân DNA","takeaway":"Nucleotide là đơn phân cấu tạo nên DNA."},{"id":"qa21-g12-l1-s1-3d21f0882c","title":"Đường trong DNA","takeaway":"Nucleotide DNA chứa deoxyribose; nucleotide RNA chứa ribose."},{"id":"qa21-g12-l1-s1-39dd306c73","title":"Khung đường–phosphate","takeaway":"Liên kết phosphodiester nối các nucleotide kế tiếp trên cùng một mạch DNA."},{"id":"qa21-g12-l1-s1-fa1368952b","title":"Nguyên tắc bổ sung DNA","takeaway":"Trong DNA mạch kép thông thường, A bắt cặp T và G bắt cặp C."},{"id":"qa21-g12-l1-s2-f78d33dd95","title":"Mã hóa thông tin","takeaway":"DNA ghi thông tin chủ yếu bằng trình tự nucleotide; cùng chiều dài không có nghĩa cùng thông tin."},{"id":"qa21-g12-l1-s2-5014686717","title":"Từ gene đến polypeptide","takeaway":"DNA → mRNA là phiên mã; mRNA → polypeptide là dịch mã."},{"id":"qa21-g12-l1-s3-a5a6118da3","title":"Tái bản bán bảo toàn","takeaway":"Sau tái bản bán bảo toàn, mỗi DNA con chứa một mạch cũ và một mạch mới."},{"id":"qa21-g12-l1-s3-4af872f66b","title":"Pha S","takeaway":"DNA nhân thường tái bản ở pha S của chu kì tế bào nhân thực."},{"id":"qa21-g12-l1-s3-8ac5b7e2e3","title":"Chiều tổng hợp DNA","takeaway":"DNA polymerase kéo dài mạch mới theo chiều 5′ → 3′, gắn nucleotide vào nhóm 3′-OH."},{"id":"qa21-g12-l2-s2-b51a5f2a57","title":"Sản phẩm của gene","takeaway":"Gene có thể quy định RNA chức năng hoặc polypeptide; không phải mọi RNA đều được dịch mã."},{"id":"qa21-g12-l2-s2-97bc61c935","title":"Mạch khuôn","takeaway":"Trong phiên mã một gene, RNA polymerase đọc mạch khuôn DNA để tạo RNA bổ sung, ngược chiều."},{"id":"qa21-g12-l2-s2-5d7c00f45b","title":"Không phải mọi gene đều có intron","takeaway":"Gene phân mảnh phổ biến ở nhân thực nhưng vẫn có gene không chứa intron."},{"id":"qa21-g12-l2-s3-156c289438","title":"Hệ gene","takeaway":"Hệ gene của sinh vật tế bào gồm toàn bộ vật chất di truyền, không chỉ các gene đang hoạt động."},{"id":"qa21-g12-l2-s4-a7fb4d0968","title":"Sản phẩm phiên mã","takeaway":"Phiên mã trực tiếp tạo RNA; sản phẩm có thể là mRNA, rRNA hoặc tRNA."},{"id":"qa21-g12-l2-s4-ea0b28afb1","title":"Cắt nối tiền mRNA","takeaway":"Cắt nối điển hình loại intron và nối các exon trên tiền mRNA, không xóa intron khỏi DNA."},{"id":"qa21-g12-l2-s4-aab4013c70","title":"Phiên mã và dịch mã ở vi khuẩn","takeaway":"Không có màng nhân giúp ribosome tiếp cận mRNA đang được tổng hợp, nên phiên mã và dịch mã có thể đồng thời."},{"id":"qa21-g12-l2-s5-94fa194d15","title":"Phiên mã ngược","takeaway":"Phiên mã ngược tổng hợp DNA trên khuôn RNA."},{"id":"qa21-g12-l2-s5-8f7dcdae7d","title":"Virus RNA và phiên mã ngược","takeaway":"Chỉ một số nhóm virus RNA dùng phiên mã ngược; nhiều nhóm nhân lên không qua DNA."},{"id":"qa21-g12-l2-s6-a97626323c","title":"Codon","takeaway":"Một codon trên mRNA gồm ba nucleotide, quy định amino acid hoặc tín hiệu kết thúc."},{"id":"qa21-g12-l2-s6-4f48299b90","title":"Tính thoái hóa của mã","takeaway":"Nhiều codon có thể cùng quy định một amino acid: đó là tính thoái hóa của mã di truyền."},{"id":"qa21-g12-l2-s7-f2e5b6beda","title":"Nơi dịch mã","takeaway":"Ribosome đọc mRNA và xúc tác tổng hợp chuỗi polypeptide."},{"id":"qa21-g12-l2-s7-e455d0c168","title":"Dịch mã không riêng pha S","takeaway":"Dịch mã diễn ra theo nhu cầu tế bào, không bị giới hạn riêng ở pha S."},{"id":"qa21-g12-l2-s7-40480d5bcf","title":"Ghép codon – anticodon","takeaway":"Anticodon của tRNA bắt cặp với codon để góp phần đưa amino acid phù hợp tới ribosome."},{"id":"qa21-g12-l2-s8-3c032afe59","title":"Môi trường và kiểu hình","takeaway":"Môi trường có thể ảnh hưởng kiểu hình qua biểu hiện gene và hoạt động tế bào dù trình tự DNA không đổi."},{"id":"qa21-g12-l3-s2-b610e0203a","title":"Allolactose","takeaway":"Allolactose gắn protein ức chế lac, làm giảm khả năng protein gắn operator."},{"id":"qa21-g12-l3-s2-d6752e78f3","title":"Operator","takeaway":"Protein ức chế lac gắn operator để cản phiên mã hiệu quả."},{"id":"qa21-g12-l3-s2-4e73029640","title":"Gene lacI","takeaway":"Gene lacI mã hóa protein ức chế lac và nằm ngoài bộ gene cấu trúc lacZYA."},{"id":"qa21-g12-l3-s2-af0450da82","title":"Khi operon lac hoạt động mạnh","takeaway":"Operon lac thường biểu hiện mạnh nhất khi có lactose và glucose thấp."},{"id":"qa21-g12-l3-s3-aa3dba7af0","title":"Chuyên hóa tế bào","takeaway":"Neuron và tế bào cơ thường có cùng hệ gene nhưng biểu hiện các tập hợp gene khác nhau."},{"id":"qa21-g12-l3-s4-ce31a11d61","title":"Điều chỉnh sản phẩm gene","takeaway":"Giảm biểu hiện gene làm thay đổi lượng RNA hoặc protein được tạo, không nhất thiết thay trình tự gene."},{"id":"qa21-g12-l4-s1-6fade71cdd","title":"Đột biến gene","takeaway":"Đột biến gene là biến đổi trình tự nucleotide của gene."},{"id":"qa21-g12-l4-s1-df6ceba769","title":"Đột biến vô nghĩa","takeaway":"Đột biến vô nghĩa có thể tạo codon kết thúc sớm, làm chuỗi polypeptide ngắn đi."},{"id":"qa21-g12-l4-s2-84415056f5","title":"Đột biến nội sinh","takeaway":"Đột biến có thể xuất hiện do sai sót tái bản hoặc biến đổi tự phát của DNA, không cần tác nhân từ ngoài."},{"id":"qa21-g12-l4-s5-6964c4b0fb","title":"Dịch khung đọc","takeaway":"Mất một nucleotide trong vùng mã hóa mà không được bù thường làm dịch khung đọc phía sau vị trí mất."},{"id":"qa21-g12-l4-s5-df15758c66","title":"Đột biến đồng nghĩa","takeaway":"Thay thế một cặp nucleotide có thể không đổi amino acid nhờ tính thoái hóa của mã di truyền."},{"id":"qa21-g12-l4-s6-63895d9402","title":"Nguồn allele mới","takeaway":"Đột biến gene tạo allele mới, cung cấp biến dị cho tiến hóa."},{"id":"qa21-g12-l5-s1-280a911ef6","title":"DNA ligase","takeaway":"DNA ligase nối bộ khung đường–phosphate bằng liên kết phosphodiester giữa các đoạn DNA thích hợp."},{"id":"qa21-g12-l5-s1-37db463555","title":"Vector","takeaway":"Vector mang DNA cần chuyển vào tế bào nhận; plasmid là một ví dụ."},{"id":"qa21-g12-l5-s2-9da9cf3938","title":"Sinh vật chuyển gene","takeaway":"Sinh vật mang gene đưa vào từ loài khác là một trường hợp chuyển gene khác loài."},{"id":"qa21-g12-l5-s2-aab2ddf8a1","title":"Lúa vàng","takeaway":"Lúa vàng được phát triển để tăng β-carotene, tiền vitamin A, trong phần hạt ăn được."},{"id":"qa21-g12-l6-s1-15dadd4a75","title":"Chất tẩy rửa và DNA","takeaway":"Trong tách chiết DNA, chất tẩy rửa giúp phá màng lipid để giải phóng thành phần tế bào."},{"id":"qa21-g12-l6-s2-18711e78f8","title":"Kết tủa DNA","takeaway":"Ethanol giúp DNA kết tủa trong điều kiện thích hợp; không tạo ra DNA mới."},{"id":"qa21-g12-l7-s1-b7d8275d98","title":"Lõi nucleosome","takeaway":"Lõi nucleosome điển hình chứa 8 phân tử histone, gồm hai bản sao mỗi loại H2A, H2B, H3, H4."},{"id":"qa21-g12-l7-s1-64c645fcd4","title":"Quan sát nhiễm sắc thể","takeaway":"Kì giữa thường thuận lợi để quan sát hình thái và lập bộ nhiễm sắc thể vì NST co đặc rõ."},{"id":"qa21-g12-l7-s2-8d03152d4d","title":"Locus","takeaway":"Locus là vị trí xác định của một gene trên nhiễm sắc thể."},{"id":"qa21-g12-l7-s2-45e03500d4","title":"Allele","takeaway":"Allele là các phiên bản của cùng một gene tại cùng locus."},{"id":"qa21-g12-l7-s3-9bd20de9b7","title":"Giữ bộ NST qua thế hệ","takeaway":"Ở vòng đời lưỡng bội điển hình, giảm phân tạo giao tử n và thụ tinh phục hồi hợp tử 2n."},{"id":"qa21-g12-l8-s1-a1be275d46","title":"Đậu Hà Lan trong thí nghiệm","takeaway":"Đậu Hà Lan tự thụ phấn và có thể lai chủ động, giúp Mendel giữ dòng thuần và kiểm soát bố mẹ."},{"id":"qa21-g12-l9-s1-ead218489d","title":"Trội không hoàn toàn","takeaway":"RR đỏ × WW trắng cho RW hồng là trội không hoàn toàn: kiểu dị hợp có kiểu hình trung gian."},{"id":"qa21-g12-l9-s1-4f825eecd6","title":"Lai hoa hồng dị hợp","takeaway":"Với RR đỏ, RW hồng, WW trắng và sức sống bằng nhau, RW × RW cho 1 đỏ : 2 hồng : 1 trắng."},{"id":"qa21-g12-l9-s2-9de7000504","title":"Đồng trội","takeaway":"Ở kiểu dị hợp đồng trội, cả hai allele biểu hiện đặc điểm riêng, như IᴬIᴮ có cả kháng nguyên A và B."},{"id":"qa21-g12-l9-s2-8dc90c75af","title":"Gene đa allele","takeaway":"Gene đa allele có hơn hai allele trong quần thể; mỗi cá thể lưỡng bội thường chỉ mang tối đa hai ở một locus."},{"id":"qa21-g12-l9-s3-ba70c23b35","title":"Hai gene cùng tạo sắc tố","takeaway":"Hai gene độc lập, chỉ A_B_ có sắc tố: AaBb × AaBb cho 9/16 con có sắc tố nếu sức sống bằng nhau."},{"id":"qa21-g12-l9-s4-8653569773","title":"Át chế","takeaway":"Tương tác át chế là gene ở locus này che ảnh hưởng kiểu hình của gene ở locus khác."},{"id":"qa21-g12-l9-s5-f534061878","title":"Đếm allele cộng gộp","takeaway":"Trong mô hình mỗi allele trội tăng 2 cm, AABb có 3 allele trội và tăng 6 cm so với mức nền."},{"id":"qa21-g12-l10-s1-f138f17b71","title":"Gene trên NST giới tính","takeaway":"NST giới tính còn mang gene cho nhiều tính trạng khác, không chỉ gene quy định giới tính."},{"id":"qa21-g12-l10-s2-54de4127d3","title":"Nguồn NST X của con trai","takeaway":"Trong hệ XX–XY, con trai nhận X từ mẹ và Y từ bố."},{"id":"qa21-g12-l10-s2-9af6ed190e","title":"Allele lặn trên X","takeaway":"Cá thể XY dễ biểu hiện allele lặn tại locus trên X không có bản sao tương ứng trên Y vì chỉ có một allele."},{"id":"qa21-g12-l10-s4-df4bedf7c0","title":"Dấu hiệu liên kết giới tính","takeaway":"Trong tổ hợp lai phù hợp, dấu hiệu liên kết giới tính có thể giúp phân biệt con đực và con cái sớm."},{"id":"qa21-g12-l11-s1-3a7701e0c1","title":"Xu hướng liên kết","takeaway":"Hai gene gần nhau trên cùng NST thường di truyền cùng nhau, nhưng trao đổi chéo có thể phá liên kết."},{"id":"qa21-g12-l11-s2-1bfb44733d","title":"Chromatid trao đổi chéo","takeaway":"Trao đổi chéo thường xảy ra giữa các chromatid không chị em của cặp NST tương đồng trong giảm phân I."},{"id":"qa21-g12-l11-s2-c8a529b265","title":"Ví dụ giao tử hoán vị","takeaway":"AB/ab có tần số hoán vị 20%: theo mô hình đối xứng, Ab và aB mỗi loại chiếm 10%."},{"id":"qa21-g12-l11-s3-3b521ce427","title":"Khoảng cách liên kết","takeaway":"Ở khoảng cách nhỏ, 1% tái tổ hợp xấp xỉ 1 cM; trao đổi chéo nhiều lần có thể làm đánh giá thấp khoảng xa."},{"id":"qa21-g12-l11-s4-d6a13c7591","title":"Gene xa trên cùng NST","takeaway":"Hai gene xa nhau trên cùng NST có thể cho tần số tái tổ hợp gần 50%."},{"id":"qa21-g12-l12-s1-34b2a491e7","title":"Lệch bội","takeaway":"Bộ NST 2n + 1 là lệch bội: thừa một NST riêng lẻ, không tăng cả bộ."},{"id":"qa21-g12-l12-s2-c196883f38","title":"Ví dụ lặp đoạn","takeaway":"Trình tự ABCDE thành ABBCDE là lặp đoạn B."},{"id":"qa21-g12-l12-s2-f7f194b144","title":"Ví dụ đảo đoạn","takeaway":"Trình tự ABCDE thành ADCBE là đảo đoạn BCD thành DCB."},{"id":"qa21-g12-l12-s3-076e13afe6","title":"Không phân li","takeaway":"Không phân li NST trong giảm phân có thể tạo giao tử n + 1."},{"id":"qa21-g12-l12-s3-4424505ee9","title":"Tự tam bội","takeaway":"Thể tự tam bội có bộ NST 3n, gồm ba bộ đơn bội."},{"id":"qa21-g12-l12-s4-268d50cc02","title":"Mất cân bằng liều gene","takeaway":"Nhiều thể lệch bội giảm sức sống do mất cân bằng liều lượng gene."},{"id":"qa21-g12-l12-s5-5754900b8e","title":"Khó tạo hạt ở cây tam bội","takeaway":"Ba bộ NST khó bắt cặp và phân li cân bằng khi giảm phân, nên cây tam bội thường khó tạo hạt hữu thụ."},{"id":"qa21-g12-l12-s6-60a9f7c89d","title":"Biến dị tổ hợp","takeaway":"Giảm phân và thụ tinh sắp xếp lại các allele có sẵn, tạo biến dị tổ hợp."},{"id":"qa21-g12-l13-s1-8b56efba64","title":"Di truyền y học","takeaway":"Di truyền y học ứng dụng kiến thức di truyền để hiểu, chẩn đoán và hỗ trợ xử lí bệnh."},{"id":"qa21-g12-l13-s2-3451ac999c","title":"Phả hệ","takeaway":"Phả hệ theo dõi tính trạng qua các thế hệ gia đình để hỗ trợ suy luận cách di truyền."},{"id":"qa21-g12-l13-s3-7be520c1ee","title":"Khả năng của NST đồ","takeaway":"NST đồ thường phát hiện thừa, thiếu cả NST hoặc biến đổi cấu trúc đủ lớn; không thay xét nghiệm trình tự DNA."},{"id":"qa21-g12-l13-s4-c74305242f","title":"Tư vấn di truyền","takeaway":"Tư vấn di truyền giải thích nguy cơ và các lựa chọn, hỗ trợ quyết định có hiểu biết."},{"id":"qa21-g12-l13-s5-7377180025","title":"Các cách của liệu pháp gene","takeaway":"Liệu pháp gene có thể bổ sung, chỉnh sửa hoặc điều chỉnh gene, không chỉ thay gene bệnh bằng gene bình thường."},{"id":"qa21-g12-l13-s6-200c1d5e1d","title":"Bổ sung gene hoạt động","takeaway":"Bổ sung bản sao gene hoạt động nhằm phục hồi sản phẩm hoặc chức năng thiếu; hiệu quả tùy bệnh và tế bào đích."},{"id":"qa21-g12-l13-s8-bb038bfc40","title":"RFLP","takeaway":"Đa hình chiều dài đoạn cắt giới hạn là khác biệt chiều dài các đoạn DNA sau cắt; tự nó không chứng minh biến thể gây bệnh."},{"id":"qa21-g12-l13-s9-7f9e28fdc3","title":"Ví dụ bệnh lặn liên kết X","takeaway":"Mẹ XᴬXᵃ, bố XᴬY, phân li bình thường: trong số con trai, xác suất mắc bệnh lặn liên kết X là 1/2."},{"id":"qa21-g12-l14-s2-a33513851b","title":"Tìm mẫu ở vật kính nhỏ","takeaway":"Vật kính nhỏ có trường nhìn rộng, giúp định vị và căn giữa vùng NST trước khi tăng độ phóng đại."},{"id":"qa21-g12-l15-s1-18dce38fcf","title":"Thí nghiệm Correns","takeaway":"Di truyền màu lá hoa bốn giờ gắn với Correns là ví dụ di truyền ngoài nhân liên quan lục lạp."},{"id":"qa21-g12-l15-s2-aca9313ab2","title":"Lá khảm","takeaway":"Cành mẹ lá khảm trong thí nghiệm Correns có thể cho con xanh, trắng hoặc khảm do phân bố lục lạp khác nhau."},{"id":"qa21-g12-l15-s3-c17e35d65e","title":"Bào quan truyền theo mẹ","takeaway":"Nhiều tính trạng bào quan truyền chủ yếu theo mẹ vì trứng cung cấp phần lớn tế bào chất và bào quan."},{"id":"qa21-g12-l15-s4-ca5c68b9f6","title":"Lai thuận nghịch chưa đủ kết luận","takeaway":"Lai thuận nghịch khác kết quả không tự chứng minh gene ở ti thể; cần xét thêm liên kết giới tính, hiệu ứng mẹ và cơ chế khác."},{"id":"qa21-g12-l15-s5-6463ae24c9","title":"Bất thụ đực trong tạo hạt lai","takeaway":"Dùng dòng mẹ bất thụ đực giúp giảm công khử đực và hạn chế tự thụ phấn."},{"id":"qa21-g12-l16-s1-49fd296ebd","title":"Kiểu gene – môi trường – kiểu hình","takeaway":"Cùng kiểu gene nhưng khác dinh dưỡng có thể khác chiều cao, thể hiện ảnh hưởng môi trường lên kiểu hình."},{"id":"qa21-g12-l16-s2-6890fa9b13","title":"Mức phản ứng","takeaway":"Mức phản ứng là tập hợp các kiểu hình của một kiểu gene trong những môi trường khác nhau."},{"id":"qa21-g12-l16-s3-7a33e6bd37","title":"Tự thụ và dòng thuần","takeaway":"Tự thụ có kiểm soát qua nhiều thế hệ thường tăng mức đồng hợp, giúp tạo dòng thuần."},{"id":"qa21-g12-l16-s4-c4df02fbdc","title":"Đánh giá trong chọn giống","takeaway":"Chọn tính trạng di truyền ổn định cần xét cơ sở di truyền và kết quả đời con, không chỉ kiểu hình cá thể."},{"id":"qa21-g12-l16-s5-1fea7ca4b9","title":"Giống và điều kiện canh tác","takeaway":"Giống lúa năng suất cao ở một nơi không bảo đảm đạt như vậy ở mọi nơi vì còn phụ thuộc môi trường và canh tác."},{"id":"qa21-g12-l17-s1-4630fdb086","title":"Nghiên cứu thường biến","takeaway":"So sánh cây cùng kiểu gene nhưng khác điều kiện cần kiểm tra giúp tách ảnh hưởng môi trường lên kiểu hình."},{"id":"qa21-g12-l17-s2-6d56aa06ef","title":"Đối chứng trong thử nước tưới","takeaway":"Khi kiểm tra lượng nước, giữ giống và các điều kiện chăm sóc khác tương đương giữa các nhóm."},{"id":"qa21-g12-l18-s1-9e7ae0250f","title":"Di truyền quần thể","takeaway":"Di truyền học quần thể theo dõi tần số allele và kiểu gene qua các thế hệ."},{"id":"qa21-g12-l18-s2-7febe9303a","title":"Ví dụ tần số allele","takeaway":"20 AA, 60 Aa, 20 aa có tần số A = (2 × 20 + 60)/(2 × 100) = 0,5."},{"id":"qa21-g12-l18-s3-b251e43d89","title":"Tần số dị hợp khi cân bằng","takeaway":"Ở cân bằng Hardy–Weinberg, p(A) = 0,7 và q(a) = 0,3 cho Aa = 2pq = 0,42."},{"id":"qa21-g12-l18-s3-4484e67ca1","title":"Điều kiện cân bằng","takeaway":"Ngẫu phối chưa đủ; mô hình Hardy–Weinberg còn cần quần thể đủ lớn, không chọn lọc, đột biến và di nhập gene."},{"id":"qa21-g12-l18-s4-6a24584688","title":"Tự thụ một thế hệ","takeaway":"Quần thể ban đầu toàn Aa, tự thụ một thế hệ và không chọn lọc: Aa còn 1/2."},{"id":"qa21-g12-l18-s4-bcdb750a84","title":"Tự thụ và tần số allele","takeaway":"Trong mô hình chỉ có tự thụ, không chọn lọc hay nhân tố khác, tần số allele không đổi."},{"id":"qa21-g12-l19-s1-0fe26f38fb","title":"Bằng chứng hóa thạch","takeaway":"Hóa thạch là bằng chứng trực tiếp về sinh vật từng tồn tại trong quá khứ."},{"id":"qa21-g12-l19-s2-ee25397464","title":"Định tuổi hóa thạch","takeaway":"Có thể ước tính tuổi qua lớp đá liên quan bằng đồng vị phù hợp; không phải mọi hóa thạch đều dùng carbon-14."},{"id":"qa21-g12-l19-s3-f7e366b9be","title":"Cơ quan tương đồng","takeaway":"Cơ quan tương đồng có nguồn gốc tiến hóa chung dù chức năng có thể khác nhau."},{"id":"qa21-g12-l19-s3-2f6d592399","title":"Cơ quan thoái hóa","takeaway":"Cơ quan thoái hóa giảm một chức năng tổ tiên nhưng có thể còn hoặc đổi chức năng."},{"id":"qa21-g12-l19-s3-13cf21d88e","title":"Cơ quan tương tự","takeaway":"Cánh côn trùng và cánh chim cùng giúp bay nhưng khác nguồn gốc: đó là cơ quan tương tự."},{"id":"qa21-g12-l19-s4-50b4702c57","title":"Bằng chứng tế bào","takeaway":"Tương đồng cơ bản về cấu trúc và cơ chế tế bào hỗ trợ nhận định sinh vật tế bào có quan hệ nguồn gốc."},{"id":"qa21-g12-l19-s5-f236bcfce6","title":"So sánh trình tự","takeaway":"So sánh trình tự DNA tương đồng, cùng các bằng chứng khác, giúp suy luận quan hệ tiến hóa."},{"id":"qa21-g12-l20-s1-21181ef91b","title":"Biến dị cần di truyền","takeaway":"Để chọn lọc tự nhiên tạo đáp ứng di truyền qua thế hệ, biến dị phải có khả năng di truyền."},{"id":"qa21-g12-l20-s2-49d51dd09e","title":"Chọn lọc nhân tạo","takeaway":"Trong chọn lọc nhân tạo, con người chọn cá thể sinh sản theo tính trạng mong muốn."},{"id":"qa21-g12-l20-s3-8770aa03d8","title":"Đích trực tiếp của chọn lọc","takeaway":"Chọn lọc tự nhiên tác động trực tiếp lên kiểu hình, qua đó làm thay đổi thành phần di truyền qua thế hệ."},{"id":"qa21-g12-l20-s4-52852e760d","title":"Kiểm tra giả thuyết","takeaway":"Giả thuyết được kiểm tra bằng dữ liệu quan sát và thí nghiệm phù hợp, không chỉ dựa vào uy tín người đề xuất."},{"id":"qa21-g12-l21-s1-469671cbf9","title":"Tiến hóa nhỏ","takeaway":"Thay đổi tần số allele của quần thể qua thế hệ là tiến hóa nhỏ, không phải cá thể tự tiến hóa trong đời."},{"id":"qa21-g12-l21-s2-430be812a0","title":"Phiêu bạt di truyền","takeaway":"Phiêu bạt di truyền thường ảnh hưởng mạnh hơn ở quần thể nhỏ."},{"id":"qa21-g12-l21-s2-4084ec5e60","title":"Dòng gene","takeaway":"Hạt phấn từ quần thể khác thụ tinh thành công là một hình thức dòng gene."},{"id":"qa21-g12-l21-s2-b28cb9098c","title":"Giao phối khác kiểu","takeaway":"Giao phối khác kiểu có thể làm tăng dị hợp; không phải mọi giao phối không ngẫu nhiên đều tăng đồng hợp."},{"id":"qa21-g12-l21-s3-b17fe05677","title":"Giá trị thích nghi","takeaway":"Giá trị thích nghi gắn trực tiếp với đóng góp di truyền cho thế hệ sau."},{"id":"qa21-g12-l21-s3-31b43c17eb","title":"Thích nghi tùy môi trường","takeaway":"Một tính trạng có lợi trong môi trường này không nhất thiết có lợi trong môi trường khác."},{"id":"qa21-g12-l21-s4-f106f0bc86","title":"Khái niệm loài sinh học","takeaway":"Khái niệm loài sinh học nhấn mạnh cách li sinh sản và có giới hạn áp dụng."},{"id":"qa21-g12-l21-s4-74e93a3c45","title":"Cách li địa lí chưa đủ","takeaway":"Hai quần thể ngăn cách địa lí chưa chắc là hai loài; còn phải xét mức cách li sinh sản."},{"id":"qa21-g12-l22-s1-f68e241000","title":"Tiến hóa lớn","takeaway":"Tiến hóa lớn nghiên cứu phân hóa, hình thành và tuyệt chủng ở quy mô trên loài."},{"id":"qa21-g12-l22-s2-ca2a3c5f17","title":"Thí nghiệm Miller","takeaway":"Thí nghiệm Miller năm 1953 tạo một số hợp chất hữu cơ, gồm amino acid, không tạo sự sống hoàn chỉnh."},{"id":"qa21-g12-l22-s2-c1f3c7560e","title":"Nguồn gốc nội cộng sinh","takeaway":"DNA riêng và ribosome kiểu vi khuẩn hỗ trợ giả thuyết ti thể có nguồn gốc nội cộng sinh."},{"id":"qa21-g12-l22-s3-4b8bfacf82","title":"Không có đích “hoàn hảo”","takeaway":"Tiến hóa gồm phân nhánh, biến đổi và tuyệt chủng; không phải thang tiến bộ hướng tới sự hoàn hảo."},{"id":"qa21-g12-l22-s4-ac4168718d","title":"Nút trên cây phát sinh","takeaway":"Nút phân nhánh biểu thị tổ tiên chung được suy luận; độ dài nhánh chỉ là thời gian khi có thang đo tương ứng."},{"id":"qa21-g12-l22-s5-bf95480b6d","title":"Người và tinh tinh","takeaway":"Người và tinh tinh hiện đại có tổ tiên chung; một loài hiện còn không phải tổ tiên trực tiếp của loài kia."},{"id":"qa21-g12-l23-s1-0e6b315419","title":"Môi trường sống","takeaway":"Môi trường gồm các yếu tố vật lí, hóa học và sinh học xung quanh có tác động đến sinh vật."},{"id":"qa21-g12-l23-s2-cba7d73f13","title":"Nhân tố hữu sinh","takeaway":"Sinh vật cạnh tranh thức ăn là nhân tố hữu sinh tác động lên sinh vật khác."},{"id":"qa21-g12-l23-s2-09e33da831","title":"Nhân tố vô sinh","takeaway":"Độ mặn là nhân tố vô sinh vì là tính chất hóa học của môi trường."},{"id":"qa21-g12-l23-s3-634cf951a0","title":"Cây ưa bóng","takeaway":"Cây ưa bóng thích nghi với mức sáng thấp hơn cây ưa sáng nhưng vẫn cần ánh sáng để quang hợp."},{"id":"qa21-g12-l23-s3-c7ee9f319b","title":"Hai vai trò của ánh sáng","takeaway":"Ánh sáng vừa cung cấp năng lượng quang hợp vừa là tín hiệu giúp cây điều chỉnh sinh trưởng, ra hoa."},{"id":"qa21-g12-l23-s4-dc1126b557","title":"Động vật nội nhiệt","takeaway":"Động vật nội nhiệt duy trì thân nhiệt chủ yếu nhờ nhiệt chuyển hóa và điều hòa mất nhiệt."},{"id":"qa21-g12-l23-s4-6d0efc421b","title":"Nhiệt độ và enzyme","takeaway":"Nhiệt độ quá cao có thể đổi cấu trúc enzyme và làm giảm hoạt động của nó."},{"id":"qa21-g12-l23-s5-c37e92070c","title":"Khoảng thuận lợi","takeaway":"Khoảng thuận lợi là khoảng của nhân tố sinh thái giúp sinh vật hoạt động tốt."},{"id":"qa21-g12-l23-s5-a41ad1e9ef","title":"Ví dụ giới hạn và thuận lợi","takeaway":"Loài chịu được 10–35°C nhưng phát triển tốt nhất ở 22–28°C có khoảng thuận lợi là 22–28°C.","detail":"Trong ví dụ này, 22–28°C là khoảng phát triển tốt nhất; 10–35°C là khoảng sống được."},{"id":"qa21-g12-l23-s6-693f1a6b29","title":"Nhịp ngày–đêm","takeaway":"Nhịp sinh học ngày–đêm có cơ chế nội sinh và được tín hiệu môi trường, như ánh sáng, điều chỉnh."},{"id":"qa21-g12-l24-s1-11f0e31988","title":"Quần thể sinh vật","takeaway":"Quần thể gồm cá thể cùng loài trong một vùng, cùng thời điểm và có liên hệ sinh sản."},{"id":"qa21-g12-l24-s2-368bb30c48","title":"Cạnh tranh cùng loài","takeaway":"Hai cây cùng loài che bóng nhau khi mọc quá dày là cạnh tranh cùng loài."},{"id":"qa21-g12-l24-s2-1c7c3c8c53","title":"Hỗ trợ cùng loài","takeaway":"Đàn cá phối hợp làm giảm nguy cơ bị săn bắt là ví dụ hỗ trợ cùng loài."},{"id":"qa21-g12-l24-s3-ea76d9740b","title":"Tính mật độ","takeaway":"Có 200 cây trên 50 m² thì mật độ = 200/50 = 4 cây/m²."},{"id":"qa21-g12-l24-s3-a4554aba04","title":"Phân bố theo nhóm","takeaway":"Nguồn nước rải rác có thể khiến cá thể tập trung quanh đó, tạo phân bố theo nhóm."},{"id":"qa21-g12-l24-s4-693273f72f","title":"Tính số lượng cuối kì","takeaway":"Ban đầu 100; sinh 20, chết 10, nhập 5, xuất 3: cuối kì 100 + 20 − 10 + 5 − 3 = 112 cá thể."},{"id":"qa21-g12-l24-s4-b93a9869d5","title":"Tăng trưởng logistic","takeaway":"Đường cong chữ S thể hiện tăng trưởng chậm lại khi quần thể tiến gần sức chứa môi trường."},{"id":"qa21-g12-l24-s4-a1da3e49f3","title":"Tăng trưởng hàm mũ","takeaway":"Mô hình hàm mũ với r > 0 giả định nguồn sống chưa giới hạn tăng trưởng, cho đường cong chữ J."},{"id":"qa21-g12-l24-s5-012a9ec3b6","title":"Biến động theo mùa","takeaway":"Số lượng ếch thường tăng vào mùa mưa là biến động theo chu kì mùa."},{"id":"qa21-g12-l24-s5-20ecaac6c2","title":"Biến động bất thường","takeaway":"Một vụ cháy rừng đột ngột làm giảm số cá thể là biến động không theo chu kì."},{"id":"qa21-g12-l24-s6-61aaa68d7f","title":"Mật độ nuôi phù hợp","takeaway":"Thả cá quá dày làm tăng cạnh tranh và nguy cơ thiếu oxygen, nên mật độ cần phù hợp nguồn lực hệ nuôi."},{"id":"qa21-g12-l25-s1-287af74b38","title":"Phạm vi khảo sát","takeaway":"Khảo sát quần thể cần xác định loài, khu vực và thời điểm trước khi thu số liệu."},{"id":"qa21-g12-l25-s2-48fc7821c2","title":"Ô tiêu chuẩn","takeaway":"Ô tiêu chuẩn phù hợp ước lượng cây cỏ ít di chuyển trong diện tích biết trước."},{"id":"qa21-g12-l25-s2-d5ad5b3c74","title":"Ước lượng từ ô mẫu","takeaway":"5 ô, mỗi ô 1 m², tổng 40 cây cho mật độ 8 cây/m²; ước lượng 800 cây trên 100 m² nếu mẫu đại diện."},{"id":"qa21-g12-l26-s1-6ede0238a9","title":"Quần xã","takeaway":"Quần xã gồm các quần thể thuộc nhiều loài cùng sống và tương tác trong một khu vực."},{"id":"qa21-g12-l26-s2-e1e216a6e6","title":"Độ phong phú và đồng đều","takeaway":"Hai quần xã có cùng số loài chưa chắc đa dạng như nhau vì độ đồng đều cũng ảnh hưởng."},{"id":"qa21-g12-l26-s2-4a2a65656d","title":"Loài chủ chốt","takeaway":"Loài chủ chốt tác động lớn lên quần xã không tương xứng với mức phong phú của nó."},{"id":"qa21-g12-l26-s2-3568c0dd27","title":"Sinh vật phân giải","takeaway":"Nấm phân giải xác lá là sinh vật phân giải, góp phần hoàn trả chất dinh dưỡng cho môi trường."},{"id":"qa21-g12-l26-s3-dd82a9452d","title":"Quan hệ cùng có lợi","takeaway":"Ong lấy mật và giúp hoa thụ phấn là quan hệ + / +: cả hai bên được lợi."},{"id":"qa21-g12-l26-s3-c4aafd84a4","title":"Kí sinh","takeaway":"Giun kí sinh được lợi, vật chủ bị hại: quan hệ + / −."},{"id":"qa21-g12-l26-s3-af9d084202","title":"Hội sinh","takeaway":"Hội sinh có dấu + / 0: một loài được lợi, loài kia không bị ảnh hưởng rõ rệt."},{"id":"qa21-g12-l26-s4-088a16c049","title":"Ổ sinh thái khác nơi ở","takeaway":"Nơi ở là “ở đâu”; ổ sinh thái còn gồm cách sử dụng nguồn sống và điều kiện tồn tại."},{"id":"qa21-g12-l26-s4-64bb33511e","title":"Phân chia nguồn sống","takeaway":"Hai loài chim kiếm ăn ở hai tầng cây khác nhau có thể giảm cạnh tranh thức ăn."},{"id":"qa21-g12-l26-s5-e7a8f0ab87","title":"Rủi ro loài ngoại lai","takeaway":"Cần đánh giá trước khi thả loài ngoại lai vì một số có thể xâm hại quần xã bản địa."},{"id":"qa21-g12-l28-s1-bf53367f09","title":"Hệ sinh thái","takeaway":"Hệ sinh thái gồm quần xã và sinh cảnh, liên hệ qua trao đổi vật chất và năng lượng."},{"id":"qa21-g12-l28-s1-ad2c35e66c","title":"Hệ mở","takeaway":"Hệ sinh thái trao đổi vật chất và năng lượng với bên ngoài nên là hệ mở."},{"id":"qa21-g12-l28-s2-a6903aacf6","title":"Nông nghiệp thâm canh","takeaway":"Hệ sinh thái nông nghiệp thâm canh thường phụ thuộc đáng kể vào đầu vào và quản lí của con người."},{"id":"qa21-g12-l29-s1-08fb492ad0","title":"Năng lượng khác vật chất","takeaway":"Năng lượng truyền qua hệ rồi phân tán thành nhiệt; vật chất có thể tuần hoàn và được tái sử dụng."},{"id":"qa21-g12-l29-s1-af9d65ecf7","title":"Nguồn năng lượng chủ yếu","takeaway":"Ánh sáng Mặt Trời là nguồn năng lượng ban đầu của phần lớn hệ sinh thái."},{"id":"qa21-g12-l29-s2-a6751f3e39","title":"Mũi tên chuỗi thức ăn","takeaway":"Trong cỏ → thỏ → cáo, mũi tên chỉ chiều truyền vật chất và năng lượng từ sinh vật bị ăn đến sinh vật ăn."},{"id":"qa21-g12-l29-s2-30110e669b","title":"Chuỗi mùn bã","takeaway":"Chuỗi thức ăn mùn bã bắt đầu từ vật chất hữu cơ đã chết."},{"id":"qa21-g12-l29-s3-3413cc8e86","title":"Lưới thức ăn","takeaway":"Nhiều chuỗi thức ăn có mắt xích chung liên kết thành lưới thức ăn."},{"id":"qa21-g12-l29-s4-7155f5baee","title":"Ví dụ bậc dinh dưỡng","takeaway":"Trong cỏ → sâu → chim: cỏ ở bậc 1, sâu bậc 2, chim bậc 3."},{"id":"qa21-g12-l29-s4-91ed74b676","title":"Sinh vật ăn tạp","takeaway":"Một loài ăn tạp có thể thuộc nhiều bậc dinh dưỡng tùy loại thức ăn và chuỗi đang xét."},{"id":"qa21-g12-l29-s5-a7c3eef221","title":"Ánh sáng và sinh khối","takeaway":"Chỉ một phần ánh sáng được quang hợp tích lũy thành sinh khối; không phải toàn bộ ánh sáng chiếu xuống."},{"id":"qa21-g12-l29-s6-a449083fa8","title":"Hao hụt năng lượng","takeaway":"Năng lượng giảm qua bậc dinh dưỡng vì một phần không được ăn, không đồng hóa và tỏa nhiệt qua hô hấp."},{"id":"qa21-g12-l29-s7-c38f8b8833","title":"Tính hiệu suất truyền","takeaway":"Bậc trước 10.000 kJ, bậc sau 1.000 kJ cùng kì cho hiệu suất 10%; đây không phải hằng số cho mọi hệ."},{"id":"qa21-g12-l29-s7-17f074d152","title":"Tháp năng lượng","takeaway":"Tháp năng lượng không đảo ngược khi tính trên cùng diện tích và thời gian."},{"id":"qa21-g12-l30-s1-e281be38ea","title":"Diễn thế","takeaway":"Diễn thế sinh thái là thay đổi thành phần và cấu trúc quần xã theo thời gian gắn với biến đổi môi trường."},{"id":"qa21-g12-l30-s2-4c96377d11","title":"Diễn thế nguyên sinh","takeaway":"Quần xã hình thành trên đá mới lộ, chưa có đất, là diễn thế nguyên sinh."},{"id":"qa21-g12-l30-s2-c95c135441","title":"Diễn thế thứ sinh","takeaway":"Rừng phục hồi sau cháy khi đất vẫn còn là diễn thế thứ sinh."},{"id":"qa21-g12-l30-s3-fd26e6ec8d","title":"Sinh vật đổi sinh cảnh","takeaway":"Cây tiên phong làm đất giàu chất hữu cơ hơn có thể tạo điều kiện cho loài đến sau trong diễn thế."},{"id":"qa21-g12-l30-s5-9d00b80359","title":"Phú dưỡng","takeaway":"Nitrogen và phosphorus dư thừa vào hồ dễ gây phú dưỡng, tảo nở hoa và suy giảm chất lượng nước."},{"id":"qa21-g12-l30-s5-2fd7b1966f","title":"Tảo chết làm thiếu oxygen","takeaway":"Vi sinh vật phân giải lượng lớn tảo chết tiêu thụ nhiều oxygen, có thể làm cá thiếu oxygen hòa tan."},{"id":"qa21-g12-l30-s6-63f2ab6bb8","title":"CO₂ và hiệu ứng nhà kính","takeaway":"CO₂ tăng do đốt nhiên liệu hóa thạch góp phần làm ấm khí hậu bằng cách tăng hấp thụ và phát xạ bức xạ hồng ngoại trong khí quyển."},{"id":"qa21-g12-l30-s7-7be25df0ef","title":"Sa mạc hóa","takeaway":"Sa mạc hóa là thoái hóa đất ở vùng khô hạn, bán khô hạn và khô cận ẩm; không chỉ là cát lan rộng."},{"id":"qa21-g12-l31-s1-90f456deee","title":"Sinh quyển","takeaway":"Sinh quyển bao gồm toàn bộ các hệ sinh thái có sự sống trên Trái Đất."},{"id":"qa21-g12-l31-s2-fee0122dcf","title":"Khí hậu và khu sinh học","takeaway":"Nhiệt độ và lượng mưa là hai yếu tố quan trọng để phân biệt các khu sinh học trên cạn."},{"id":"qa21-g12-l31-s2-8f00bc53a3","title":"Rừng mưa nhiệt đới","takeaway":"Rừng mưa nhiệt đới điển hình có khí hậu ấm, ẩm và nhiều tầng thực vật."},{"id":"qa21-g12-l31-s3-b796a1f142","title":"Carbon đi vào chất hữu cơ","takeaway":"Trong phần lớn hệ sinh thái, quang hợp đưa carbon vô cơ từ CO₂ vào chất hữu cơ."},{"id":"qa21-g12-l31-s3-c1c6e679d7","title":"Vai trò của sinh vật phân giải","takeaway":"Sinh vật phân giải hoàn trả chất dinh dưỡng từ chất hữu cơ về môi trường, giúp vật chất tiếp tục được sử dụng."},{"id":"qa21-g12-l33-s1-4fde27e590","title":"Phục hồi hệ sinh thái","takeaway":"Sinh thái học phục hồi hỗ trợ hệ sinh thái đã suy thoái lấy lại cấu trúc, chức năng và khả năng tự duy trì phù hợp."},{"id":"qa21-g12-l33-s1-cb32ed375d","title":"Sinh thái học bảo tồn","takeaway":"Bảo tồn hướng đến bảo vệ đa dạng sinh học và các quá trình sinh thái, không chỉ bảo vệ từng cá thể."},{"id":"qa21-g12-l33-s2-a44e2187d9","title":"Dịch vụ hệ sinh thái","takeaway":"Rừng điều hòa dòng nước là một dịch vụ hệ sinh thái: một chức năng của tự nhiên đem lại lợi ích cho con người."},{"id":"qa21-g12-l33-s2-6d0ef29801","title":"Phân mảnh sinh cảnh","takeaway":"Chia sinh cảnh thành các mảnh nhỏ có thể làm giảm kết nối và dòng gene giữa các quần thể."},{"id":"qa21-g12-l33-s3-27c705c729","title":"Bảo tồn nguyên vị","takeaway":"Bảo tồn nguyên vị bảo vệ loài ngay trong sinh cảnh tự nhiên của chúng."},{"id":"qa21-g12-l33-s3-23eeef625a","title":"Bảo tồn chuyển vị","takeaway":"Lưu hạt trong ngân hàng hạt là bảo tồn chuyển vị: giữ vật liệu di truyền ngoài sinh cảnh tự nhiên."},{"id":"qa21-g12-l33-s4-d7d8fab9fc","title":"Ba cấp độ đa dạng sinh học","takeaway":"Đa dạng sinh học gồm đa dạng gene, đa dạng loài và đa dạng hệ sinh thái."},{"id":"qa21-g12-l33-s4-9ac8992cfc","title":"Rủi ro của quần thể nhỏ","takeaway":"Quần thể nhỏ bị cô lập lâu dài dễ chịu tác động của phiêu bạt di truyền và giao phối cận huyết."},{"id":"qa21-g12-l33-s5-dd11f50e13","title":"Xung đột với động vật hoang dã","takeaway":"Giảm tiếp xúc nguy hiểm và bảo vệ sinh cảnh là hướng quản lí xung đột người–động vật hoang dã."},{"id":"qa21-g12-l33-s6-530f52cd67","title":"Hành lang sinh thái","takeaway":"Hành lang nối các mảnh sinh cảnh có thể tăng di chuyển và trao đổi gene; hiệu quả tùy loài và điều kiện."},{"id":"qa21-g12-l33-s6-040f626feb","title":"Ưu tiên loài đặc hữu bị đe dọa","takeaway":"Loài đặc hữu có phạm vi phân bố hẹp. Mất sinh cảnh của chúng có thể dẫn đến tuyệt chủng toàn cầu."},{"id":"qa21-g12-l33-s7-e6821a995f","title":"Xử lí sinh học","takeaway":"Dùng vi sinh vật phân hủy chất ô nhiễm hữu cơ là một ví dụ về xử lí sinh học."},{"id":"qa21-g12-l33-s7-55dc19e58f","title":"Đánh giá phục hồi","takeaway":"Sự tái sinh và chức năng hệ sinh thái được duy trì có ý nghĩa lâu dài hơn việc chỉ đếm số cây đã trồng."},{"id":"qa21-g12-l33-s8-097e1a1155","title":"Khai thác thủy sản bền vững","takeaway":"Mức khai thác cần dựa vào trữ lượng, khả năng tái tạo và biến động của quần thể, không chỉ tốc độ sinh sản."},{"id":"qa21-g12-l34-s1-0719b6d340","title":"Phát triển bền vững","takeaway":"Đáp ứng nhu cầu hiện tại không được làm tổn hại khả năng đáp ứng nhu cầu của các thế hệ tương lai."},{"id":"qa21-g12-l34-s2-b339e9fc4e","title":"Ba phương diện bền vững","takeaway":"Phát triển bền vững phải xét kinh tế, xã hội và môi trường cùng nhau; các mục tiêu có thể hỗ trợ hoặc xung đột."},{"id":"qa21-g12-l34-s3-b4faba565a","title":"Nông nghiệp bền vững","takeaway":"Bảo vệ đất và dùng nước, phân bón hợp lí giúp duy trì sản xuất lâu dài."},{"id":"qa21-g12-l34-s3-02187c68d9","title":"Khuếch đại sinh học","takeaway":"Một số chất độc khó phân hủy có thể tăng nồng độ ở các bậc dinh dưỡng cao qua chuỗi thức ăn."},{"id":"qa21-g12-l34-s4-3ee0130637","title":"Giảm ô nhiễm tại nguồn","takeaway":"Ưu tiên ngăn và xử lí chất thải trước khi xả. Pha loãng không làm mất tổng lượng chất thải."},{"id":"qa21-g12-l34-s5-55e551ffc3","title":"Tài nguyên tái tạo vẫn có giới hạn","takeaway":"Tốc độ khai thác có thể vượt khả năng phục hồi của tài nguyên tái tạo, dẫn đến suy kiệt."},{"id":"qa21-g12-l34-s6-e8a986042c","title":"Dân số và mức tiêu dùng","takeaway":"Áp lực môi trường phụ thuộc cả số dân, mức tiêu dùng, công nghệ và cách quản lí."},{"id":"qa21-g12-l34-s7-5a8c3b1440","title":"Giáo dục môi trường","takeaway":"Giáo dục môi trường gắn hiểu biết với kĩ năng và khả năng hành động có trách nhiệm."},{"id":"qa21-g12-l34-s8-40325f5c06","title":"Giảm lãng phí tài nguyên","takeaway":"Giảm đồ dùng một lần và tái sử dụng khi phù hợp giúp kéo dài vòng đời sản phẩm và hạn chế rác từ đầu."},{"id":"qa21-g12-l37-s0-7025dedd9d","title":"Southern blot","takeaway":"Southern blot dùng mẫu dò bổ sung để phát hiện đoạn DNA mục tiêu sau khi tách và chuyển DNA lên màng."},{"id":"qa21-g12-l37-s0-c70c6ba8f9","title":"Mẫu dò nhận diện DNA","takeaway":"Mẫu dò Southern blot nhận diện vùng DNA đích nhờ bắt cặp bổ sung; độ đặc hiệu còn tùy điều kiện lai và rửa."},{"id":"qa21-g12-l37-s0-80b9d96c24","title":"Biến tính DNA trước khi lai","takeaway":"Biến tính tách hai mạch DNA để mẫu dò tiếp cận mạch đích, không phải phá hủy trình tự DNA."},{"id":"qa21-g12-l37-s0-9891194912","title":"Màng trong Southern blot","takeaway":"Sau điện di, DNA được chuyển lên màng nylon hoặc nitrocellulose để lai mẫu dò và phát hiện."},{"id":"qa21-g12-l37-s0-bd29fe32eb","title":"Enzyme cắt giới hạn","takeaway":"Trong phân tích RFLP, enzyme cắt giới hạn cắt DNA tại các trình tự nhận biết, tạo các mảnh có độ dài khác nhau."},{"id":"qa21-g12-l37-s0-ab4934de8d","title":"Nhãn của mẫu dò","takeaway":"Southern blot có thể dùng nhãn phóng xạ hoặc không phóng xạ; nhãn giúp phát hiện tín hiệu."},{"id":"qb22-qb10-mcCNTHHVN-level2-1","title":"Nước không phải nhiên liệu","takeaway":"Nước là dung môi và tham gia chuyển hóa, nhưng không cung cấp năng lượng như chất dinh dưỡng glucose."},{"id":"qb22-qb10-mcCNTHHVN-level3-0","title":"Mồ hôi làm mát cơ thể","takeaway":"Nước nhận nhiệt để bay hơi. Mồ hôi bay hơi lấy nhiệt từ bề mặt da, giúp cơ thể thải bớt nhiệt."},{"id":"qb22-qb10-mcCNTHHVN-level2-4","title":"Cùng công thức, khác cấu trúc","takeaway":"Hai phân tử có cùng công thức phân tử vẫn có thể khác tính chất do cách liên kết hoặc sắp xếp nguyên tử khác nhau."},{"id":"qb22-qb10-mcTBNT-level2-0","title":"Lưới nội chất hạt","takeaway":"Ribosome bám ở bề mặt phía tế bào chất làm lưới nội chất hạt khác lưới nội chất trơn."},{"id":"qb22-qb10-mcTBNT-level1-11","title":"Bộ máy Golgi","takeaway":"Golgi chỉnh sửa, phân loại và đóng gói sản phẩm từ lưới nội chất, rồi phân phối bằng túi vận chuyển."},{"id":"qb22-qb10-mcTBNT-level1-12","title":"Catalase và H₂O₂","takeaway":"Catalase trong peroxisome phân giải H₂O₂ thành nước và oxygen, hạn chế độc tính của H₂O₂."},{"id":"qb22-qb10-mcTBNT-level1-13","title":"Hai màng của ti thể","takeaway":"Ti thể có màng ngoài và màng trong. Màng trong gấp nếp tạo các mào."},{"id":"qb22-qb10-mcTBNT-level1-17","title":"Chất nền lục lạp","takeaway":"Stroma là vùng dịch bao quanh hệ thylakoid bên trong lục lạp; đây là nơi diễn ra chu trình Calvin."},{"id":"qb22-qb10-mcTBNT-level1-10","title":"Ribosome không có màng","takeaway":"Ribosome gồm rRNA và protein, không được bao bọc bởi một màng riêng."},{"id":"qb22-qb10-mcTBNT-level2-11","title":"Không bào trung tâm","takeaway":"Không bào trung tâm của tế bào thực vật chứa dịch, dự trữ nước và chất tan, góp phần duy trì sức trương."},{"id":"qb22-qb10-mcTBNT-level1-14","title":"Vị trí sắc tố quang hợp","takeaway":"Trong lục lạp, sắc tố thu nhận ánh sáng nằm chủ yếu trên màng thylakoid."},{"id":"qb22-qb10-mcTBNT-level2-15","title":"Bộ khung xương tế bào","takeaway":"Vi ống và các sợi protein giúp duy trì hình dạng, tổ chức và vận chuyển bên trong tế bào."},{"id":"qb22-qb10-mcTBNT-level2-18","title":"Protein màng","takeaway":"Protein màng có nhiều chức năng, trong đó có vận chuyển chất và tiếp nhận tín hiệu; chức năng tùy loại protein."},{"id":"qb22-qb10-mcTDC-level1-1","title":"Aquaporin","takeaway":"Aquaporin là kênh giúp nước đi nhanh qua màng; nước cũng có thể khuếch tán chậm qua lớp lipid."},{"id":"qb22-qb10-mcTDC-level2-0","title":"Khuếch tán qua lớp phospholipid","takeaway":"Các phân tử nhỏ, không phân cực dễ khuếch tán trực tiếp qua lõi kị nước của lớp kép phospholipid."},{"id":"qb22-qb10-mcTDC-level1-16","title":"Năng lượng cho vận chuyển chủ động","takeaway":"Vận chuyển chủ động cần nguồn năng lượng để vận chuyển ngược gradient thích hợp; vận chuyển thụ động không dùng cơ chế đó."},{"id":"qb22-qb10-mcTDC-level1-17","title":"Nhập bào","takeaway":"Khi nhập bào, màng sinh chất lõm vào, bao lấy vật chất bên ngoài rồi tạo túi đưa vào tế bào."},{"id":"qb22-qb10-mcTDC-level1-19","title":"Xuất bào","takeaway":"Khi xuất bào, túi tiết hợp với màng sinh chất và giải phóng chất chứa bên trong ra ngoài tế bào."},{"id":"qb22-qb10-mcTDC-level2-9","title":"Co nguyên sinh","takeaway":"Trong môi trường ưu trương, nước rời tế bào thực vật; khối nguyên sinh co lại và màng tách khỏi thành tế bào."},{"id":"qb22-qb10-mcTDC-level3-2","title":"Rau trong nước muối đậm đặc","takeaway":"Nước muối đậm đặc tạo môi trường ưu trương. Nước thẩm thấu từ tế bào rau ra ngoài, làm giảm sức trương."},{"id":"qb22-qb10-mcTDC-level3-1","title":"Thành tế bào chống sức trương","takeaway":"Trong nước cất, tế bào thực vật thường không vỡ vì thành tế bào tạo lực cản khi tế bào nhận nước và trương lên."},{"id":"qb22-qb10-mcCKTBVNP-level1-1","title":"Trình tự chu kì tế bào","takeaway":"Chu kì điển hình: G₁ → S → G₂ → M, tương ứng sinh trưởng → nhân đôi DNA → chuẩn bị → phân chia."},{"id":"qb22-qb10-mcCKTBVNP-level1-7","title":"Nhân đôi DNA ở pha S","takeaway":"DNA trong nhân được nhân đôi ở pha S, tạo hai chromatid chị em cho mỗi nhiễm sắc thể."},{"id":"qb22-qb10-mcCKTBVNP-level2-4","title":"Quan sát NST ở kì giữa","takeaway":"Ở kì giữa, NST đã co xoắn mạnh, ngắn và dày nên dễ quan sát hình dạng."},{"id":"qb22-qb10-mcCKTBVNP-level2-2","title":"Điểm kiểm soát chu kì","takeaway":"Điểm kiểm soát kiểm tra điều kiện trước khi chuyển giai đoạn; phát hiện vấn đề có thể làm chu kì bị trì hoãn."},{"id":"qb22-qb10-mcCKTBVNP-level2-5","title":"Phân chia tế bào chất","takeaway":"Thành tế bào thực vật cứng nên tế bào tạo vách mới ở giữa, thay vì chỉ thắt màng như tế bào động vật."},{"id":"qb22-qb10-mcQTGP-level1-1","title":"Giảm từ 2n xuống n","takeaway":"Giảm phân bình thường của tế bào lưỡng bội tạo tế bào đơn bội n, nhờ các cặp NST tương đồng tách nhau ở giảm phân I."},{"id":"qb22-qb10-mcQTGP-level1-2","title":"Trao đổi chéo ở kì đầu I","takeaway":"Ở kì đầu I, NST tương đồng tiếp hợp; các chromatid không chị em có thể trao đổi đoạn."},{"id":"qb22-qb10-mcQTGP-level2-6","title":"Một lần nhân đôi, hai lần phân chia","takeaway":"Giảm phân gồm hai lần phân chia nhân sau một lần nhân đôi DNA; không nhân đôi DNA giữa giảm phân I và II."},{"id":"qb22-qb10-mcQTGP-level2-1","title":"Đếm NST ở kì sau I","takeaway":"Một tế bào lợn 2n = 38 ở kì sau I có 38 NST kép và 76 chromatid trong cả tế bào; chị em chưa tách nhau."},{"id":"qb22-qb10-mcQTGP-level2-2","title":"Đếm chromatid ở kì giữa I","takeaway":"Ruồi giấm 2n = 8: mỗi tế bào ở kì giữa I có 16 chromatid. Năm tế bào có 5 × 16 = 80 chromatid."},{"id":"qb22-qb10-mcQTGP-level2-7","title":"Tiếp hợp NST tương đồng","takeaway":"Tiếp hợp các NST tương đồng là đặc trưng của giảm phân I, không có trong nguyên phân bình thường."},{"id":"qb22-qb10-mcCNTB-level1-14","title":"Nhân cây bằng nuôi cấy mô","takeaway":"Nuôi cấy mô tế bào có thể nhân nhanh nhiều cây từ một lượng mô cây mẹ nhỏ trong điều kiện thích hợp."},{"id":"qb22-qb10-mcCNTB-level1-2","title":"Hai khả năng của tế bào gốc","takeaway":"Tế bào gốc có khả năng tự làm mới và biệt hóa thành các tế bào chuyên hóa phù hợp."},{"id":"qb22-qb10-mcCNTB-level1-16","title":"Nuôi cấy theo con đường mô sẹo","takeaway":"Trình tự khái quát: tách mô → tạo mô sẹo → tái sinh cây → chuyển ra vườn ươm."},{"id":"qb22-qb10-mcCNTB-level2-1","title":"Nguồn tế bào gốc phôi","takeaway":"Tế bào gốc phôi động vật có vú thường được lấy từ khối tế bào bên trong phôi nang."},{"id":"qb22-qb10-mcSTSSVSV-level1-3","title":"Nuôi cấy không liên tục","takeaway":"Không thường xuyên bổ sung dinh dưỡng hoặc lấy dịch nuôi ra; dinh dưỡng giảm và sản phẩm chuyển hóa tích lũy."},{"id":"qb22-qb10-mcSTSSVSV-level1-8","title":"Tính số tế bào sau phân đôi","takeaway":"Một vi khuẩn phân đôi mỗi 20 phút, không có tế bào chết: sau 200 phút có 10 lần phân đôi, tạo 2¹⁰ = 1.024 tế bào."},{"id":"qb22-qb10-mcSTSSVSV-level1-10","title":"Nhân tố sinh trưởng","takeaway":"Đó là chất vi sinh vật cần với lượng nhỏ nhưng không tự tổng hợp được, nên phải nhận từ môi trường."},{"id":"qb22-qb10-mcSTSSVSV-level2-3","title":"Làm lạnh và vi sinh vật","takeaway":"Nhiệt độ thấp làm chậm sinh trưởng của nhiều vi sinh vật; bảo quản lạnh không bảo đảm giết hết chúng."},{"id":"qb22-qb10-mcKQVR-level1-11","title":"Capsomer","takeaway":"Capsomer là các đơn vị hình thái cấu tạo vỏ protein capsid của virus."},{"id":"qb22-qb10-mcKQVR-level1-19","title":"Giai đoạn hấp phụ của virus","takeaway":"Hấp phụ là bước virus bám đặc hiệu vào thụ thể tế bào chủ, trước khi xâm nhập."},{"id":"qb22-qb11-mcTDNVK-level3-9","title":"Tính cường độ thoát hơi nước","takeaway":"Lá mất 0,08 g nước trong 15 phút, diện tích 0,5 dm²: 15 phút = 0,25 giờ; cường độ = 0,08/(0,5 × 0,25) = 0,64 g/(dm²·giờ)."},{"id":"qb22-qb11-mcTDNVK-level3-10","title":"Magnesium và diệp lục","takeaway":"Mg nằm ở trung tâm phân tử diệp lục; Fe hỗ trợ quá trình tổng hợp diệp lục nhưng không nằm ở vị trí đó."},{"id":"qb22-qb11-mcTDNVK-level3-12","title":"Phosphorus trong tế bào","takeaway":"Phosphorus (P) có trong các nhóm phosphate của ATP, nucleic acid và phospholipid."},{"id":"qb22-qb11-mcTDNVK-level2-24","title":"Động lực gây ứ giọt","takeaway":"Khi rễ hút nước mạnh nhưng thoát hơi nước yếu, áp suất rễ đẩy dịch mạch gỗ qua thủy khổng tạo giọt ở mép hoặc đầu lá."},{"id":"qb22-qb11-mcTDNVK-level2-16","title":"Nấm rễ và hấp thụ khoáng","takeaway":"Sợi nấm mở rộng vùng tiếp xúc với đất, hỗ trợ cây nhận nước và khoáng; cây cung cấp chất hữu cơ cho nấm."},{"id":"qb22-qb11-mcSTPTOTV-level3-3","title":"Sinh trưởng của thân ngô","takeaway":"Thân ngô không có tầng sinh mạch hoạt động kiểu cây gỗ điển hình, nên không lớn lên bằng cơ chế thứ cấp đó."},{"id":"qb22-qb11-mcSTPTOTV-level3-2","title":"Sinh trưởng sơ cấp","takeaway":"Mô phân sinh đỉnh tạo tế bào mới, giúp thân và rễ tăng chiều dài."},{"id":"qb22-qb11-mcSTPTOTV-level3-0","title":"Gibberellin và nảy mầm","takeaway":"Gibberellin thường hỗ trợ phá ngủ và huy động chất dự trữ để nảy mầm; đáp ứng phụ thuộc loài và điều kiện."},{"id":"qb22-qb11-mcSTPTOTV-level2-0","title":"Ưu thế ngọn","takeaway":"Auxin từ ngọn góp phần duy trì ưu thế ngọn; cytokinin có thể thúc đẩy chồi bên phát triển."},{"id":"qb22-qb11-mcSTPTOTV-level2-2","title":"Ethylene và già hóa","takeaway":"Ethylene thường thúc đẩy già hóa và rụng lá; cytokinin thường làm chậm già hóa ở lá."},{"id":"qb22-qb11-mcSTPTOTV-level3-1","title":"Tạo quả đơn tính","takeaway":"Ở cây đáp ứng phù hợp, auxin hoặc gibberellin có thể kích thích bầu phát triển không cần thụ tinh, tạo quả không hạt."},{"id":"qb22-qb11-mcCUODV-level2-6","title":"Tiếng hót bảo vệ lãnh thổ","takeaway":"Khi chim đực hót để báo khu vực đã có chủ, tiếng hót đó thể hiện tập tính bảo vệ lãnh thổ."},{"id":"qb22-qb11-mcCUODV-level2-7","title":"Quen nhờn","takeaway":"Giảm đáp ứng sau nhiều lần gặp cùng kích thích vô hại là quen nhờn, như rùa giảm phản ứng rụt đầu."},{"id":"qb22-qb11-mcCUODV-level2-8","title":"Tập tính học được","takeaway":"Trẻ học bơi là ví dụ tập tính hình thành qua trải nghiệm và luyện tập.","detail":"Kĩ năng bơi được cải thiện nhờ trải nghiệm và luyện tập."},{"id":"qb22-qb11-mcCUODV-level2-9","title":"Điều kiện hóa hành động","takeaway":"Chó được thưởng sau khi ngồi theo yêu cầu có xu hướng lặp lại hành vi: hành động được liên kết với hậu quả."},{"id":"qb22-qb11-mcCUODV-level3-0","title":"Chiều truyền qua synapse hóa học","takeaway":"Chất dẫn truyền đi từ tận cùng trước synapse → khe synapse → thụ thể sau synapse."},{"id":"qb22-qb11-mcSSOTV-level2-1","title":"Thân bò của dâu tây","takeaway":"Dâu tây sinh sản sinh dưỡng tự nhiên bằng thân bò; chồi trên thân bò có thể ra rễ tạo cây mới."},{"id":"qb22-qb11-mcSSOTV-level2-2","title":"Thân rễ của gừng","takeaway":"Thân rễ gừng nằm dưới đất và mang chồi; chồi có thể phát triển thành cây mới."},{"id":"qb22-qb11-mcSSOTV-level2-5","title":"Bào tử của dương xỉ","takeaway":"Dương xỉ là thực vật có mạch không hạt, tạo bào tử; bào tử phát triển thành thể giao tử trong vòng đời."},{"id":"qb22-qb11-mcKQSSSV-level1-2","title":"Vô tính và hữu tính","takeaway":"Sinh sản vô tính không có sự hợp nhất giao tử; sinh sản hữu tính có sự hợp nhất giao tử."},{"id":"qb22-qb11-mcKQSSSV-level1-4","title":"Dấu hiệu của sinh sản hữu tính","takeaway":"Dấu hiệu cốt lõi là sự hợp nhất giao tử, không nhất thiết phải có hai cơ thể khác nhau vì có loài tự thụ tinh."},{"id":"qb22-qb11-mcSTPTDV-level2-0","title":"Nguồn tiết GH","takeaway":"Ở người, hormone sinh trưởng GH được tiết chủ yếu từ thùy trước tuyến yên."},{"id":"qb22-qb11-mcSSODV-level2-1","title":"Progesterone sau rụng trứng","takeaway":"Progesterone do thể vàng tiết ra giúp duy trì niêm mạc tử cung sau rụng trứng."},{"id":"qb22-qb11-mcSSODV-level2-2","title":"FSH và LH","takeaway":"FSH và LH từ thùy trước tuyến yên tác động lên tuyến sinh dục, tham gia điều hòa tạo giao tử và tiết hormone sinh dục."},{"id":"qb22-qb12-mcc2-level1-20","title":"Lai phân tích","takeaway":"Khi A trội hoàn toàn, lai cơ thể kiểu hình trội với aa để phân biệt AA và Aa: AA × aa cho toàn Aa; Aa × aa có thể cho Aa và aa."},{"id":"qb22-qb12-mcc2-level1-21","title":"Phép lai Aa × AA","takeaway":"Với A trội hoàn toàn, đời con lí thuyết có 1 AA : 1 Aa, tức hai kiểu gene nhưng chỉ một kiểu hình trội."},{"id":"qb22-qb12-mcc2-level2-0","title":"Phân li allele ở Aa","takeaway":"Aa giảm phân bình thường, không có sai lệch phân li, tạo 1/2 giao tử A và 1/2 giao tử a."},{"id":"qb22-qb12-mcc2-level2-3","title":"Lai hai cặp tính trạng","takeaway":"AaBb × AaBb, hai gene độc lập và trội hoàn toàn: A_B_ : A_bb : aaB_ : aabb = 9 : 3 : 3 : 1."},{"id":"qb22-qb12-mcc2-level2-4","title":"Ô Punnett không phải kiểu gene","takeaway":"AaBb × AaBb, mỗi bên tạo 4 loại giao tử, có 4 × 4 = 16 ô tổ hợp; không phải 16 kiểu gene khác nhau."},{"id":"qb22-qb12-mcc2-level2-6","title":"Lai thuận nghịch","takeaway":"Lai nghịch đổi vai trò cho và nhận giao tử của hai kiểu bố mẹ; ví dụ đổi cây cao cho phấn thành cây cao nhận phấn."},{"id":"qb22-qb12-mcc2-level3-2","title":"Ba kiểu gene từ Aa × Aa","takeaway":"Phân li bình thường, các hợp tử sống như nhau: Aa × Aa tạo AA, Aa và aa; hai cách ghép A với a đều là Aa."},{"id":"qb22-qb12-mcc2-level3-4","title":"Lai phân tích hai gene độc lập","takeaway":"AaBb × aabb, hai gene độc lập và trội hoàn toàn, cho bốn kiểu hình với tỉ lệ 1 : 1 : 1 : 1."},{"id":"qb22-qb12-mcc3-level2-3","title":"Nhóm gene liên kết và số NST","takeaway":"Theo mô hình một nhóm liên kết cho mỗi NST đơn bội, loài lưỡng bội có n = 12 nhóm liên kết thì 2n = 24."},{"id":"qb22-qb12-mcc3-level3-1","title":"Đếm giao tử của các nhóm độc lập","takeaway":"Aa BB DE/de, A độc lập với D–E và D–E liên kết hoàn toàn: số loại giao tử = 2 × 1 × 2 = 4."},{"id":"qb22-qb12-mcc3-level3-2","title":"Giao tử khi liên kết hoàn toàn","takeaway":"AB/ab giảm phân bình thường, không hoán vị giữa hai locus, chỉ tạo giao tử AB và ab."},{"id":"qb22-qb12-mcc3-level3-3","title":"Xác suất giao tử dAb","takeaway":"Dd Ab/aB, D độc lập với A–B và A–B liên kết hoàn toàn: P(dAb) = 1/2 × 1/2 = 1/4 = 25%."},{"id":"qb22-qb12-mcc3-level3-4","title":"Kiểu gene tính cả pha liên kết","takeaway":"Loài lưỡng bội, ba gene cùng cặp NST thường có 2, 3, 4 allele: nếu mọi tổ hợp đều tồn tại, có 24 loại NST và 24 × 25/2 = 300 kiểu gene."},{"id":"qb22-qb12-mcc3-level3-6","title":"Ghép các giao tử liên kết","takeaway":"AB/ab × aB/ab, liên kết hoàn toàn và phân li bình thường, tạo bốn kiểu gene: AB/aB, AB/ab, ab/aB, ab/ab."},{"id":"qb22-qb12-mcc3-level3-8","title":"Tỉ lệ kiểu hình từ gene liên kết","takeaway":"A cao, B tròn, trội hoàn toàn; Ab/aB × Ab/ab, liên kết hoàn toàn: chỉ aB × Ab tạo cây cao, tròn, với tỉ lệ 1/4."},{"id":"qb22-qb12-mcBSMD-level1-2","title":"Phép lai nhóm máu ABO","takeaway":"Theo di truyền ABO thông thường, Iᴬi × Iᴮi có thể sinh con nhóm A, B, AB hoặc O."},{"id":"qb22-qb12-mcBSMD-level1-4","title":"Gene đa hiệu","takeaway":"Đa hiệu là hiện tượng một gene ảnh hưởng đến nhiều tính trạng, do sản phẩm của gene tham gia nhiều hoạt động."},{"id":"qb22-qb12-mcDTQT-level1-7","title":"Tính tần số allele trực tiếp","takeaway":"Quần thể lưỡng bội có 280 AA, 640 Aa, 80 aa: p(A) = (2 × 280 + 640)/(2 × 1.000) = 0,60, không cần giả định cân bằng."},{"id":"qb22-qb12-mcDTQT-level1-8","title":"Suy allele từ tần số aa","takeaway":"Ở cân bằng Hardy–Weinberg của gene A/a, aa = 0,16 ⇒ q(a) = 0,40 ⇒ p(A) = 0,60."},{"id":"qb22-qb12-mcDTQT-level1-12","title":"Đếm kiểu gene đồng hợp","takeaway":"Ở loài lưỡng bội, một gene trên NST thường có 5 allele thì tối đa có 5 kiểu gene đồng hợp."},{"id":"qb22-qb12-mcDTQT-level1-13","title":"Tần số dị hợp ở cân bằng","takeaway":"Gene A/a ở cân bằng Hardy–Weinberg, q(a) = 0,15: p = 0,85 và Aa = 2pq = 0,255 = 25,5%."},{"id":"qb22-qb12-mcDTQT-level2-3","title":"Hợp tử mang ít nhất một a","takeaway":"Nếu 10% giao tử ở mỗi giới mang a và thụ tinh ngẫu nhiên, P(Aa hoặc aa) = 1 − P(AA) = 1 − 0,9² = 19%."},{"id":"qb22-qb12-mcDTQT-level3-0","title":"Tự thụ phấn qua ba thế hệ","takeaway":"P có 70% Aa, 30% aa; tự thụ phấn 3 thế hệ, không chọn lọc: F₃ có 8,75% Aa và 30,625% AA. Nếu A trội hoàn toàn, kiểu hình trội = 39,375%."},{"id":"qb22-qb12-mcDTQT-level3-2","title":"Cấu trúc quần thể tự thụ phấn","takeaway":"P: 0,2 AA : 0,6 Aa : 0,2 aa; tự thụ phấn 2 thế hệ, không chọn lọc: F₂ = 0,425 AA : 0,15 Aa : 0,425 aa."},{"id":"qb22-qb12-mcSTHQT-level1-0","title":"Thành phần loài của quần xã","takeaway":"Thành phần loài là đặc trưng của quần xã nhiều loài, không phải thành phần của một quần thể đơn loài."},{"id":"qb22-qb12-mcSTHQT-level1-5","title":"Đọc tháp tuổi","takeaway":"Tháp tuổi đáy rộng cho biết nhóm cá thể non chiếm tỉ lệ lớn; đó là tiềm năng tăng trưởng, không bảo đảm quần thể luôn tăng."},{"id":"qb22-qb12-mcSTHQT-level2-2","title":"Tự tỉa thưa","takeaway":"Cây mọc quá dày cạnh tranh cùng loài về ánh sáng, nước và khoáng; một số cây yếu chết dần tạo hiện tượng tự tỉa thưa."},{"id":"qb22-qb12-mcSTHQX-level1-0","title":"Vật ăn thịt và con mồi","takeaway":"Sư tử săn và ăn trâu rừng là quan hệ vật ăn thịt–con mồi, không phải cùng cạnh tranh một nguồn thức ăn."},{"id":"qb22-qb12-mcSTHQX-level2-5","title":"Cộng sinh ở dạ cỏ","takeaway":"Vi sinh vật dạ cỏ nhận nơi sống và thức ăn; bò hưởng sản phẩm phân giải cellulose. Cả hai bên đều có lợi."},{"id":"qb22-qb12-mcSTHQX-level3-2","title":"Nuôi ghép và ổ sinh thái","takeaway":"Nuôi cá có thức ăn và tầng kiếm ăn khác nhau có thể tận dụng nguồn sống tốt hơn; vẫn cần quản lí mật độ và chất lượng nước."}]};
